const $=s=>document.querySelector(s), E=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=x=>Number(x).toLocaleString('ko-KR')+'원';
const cloud=new URLSearchParams(location.search).get('cloud')==='1',demoKey=M.KEY+'-local-demo-v2';let actualAccess=null;
let d,storageProblem=false;try{const saved=cloud?null:localStorage.getItem(demoKey);d=saved?JSON.parse(saved):M.seed();if(d.version!==1||!Array.isArray(d.students))throw Error();}catch{storageProblem=true;d=M.seed()}
const initialView=new URLSearchParams(location.search).get('screen');
let view=initialView==='student'?'student':initialView==='books'?'books':initialView==='daily'?'daily':initialView==='students'?'students':initialView==='tuition'?'tuition':initialView==='reports'?'reports':initialView==='attendance'?'attendance':initialView==='announcements'?'announcements':'dashboard',role=initialView==='student'?'student':'admin',teacherId='t1',studentId='s1',selectedAssignment='a1',unit=1,attDate=M.today(),invoiceMonth=M.month(),reportMonth=M.month(),reportId=null,studentQuery='',studentListStatus='active',teacherListStatus='active',draftSteps=[],draftBook=null,draftUnit=0,dirty=false;
