const actions={};function on(name,fn){actions[name]=fn}const btn=(label,action,cls='secondary',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const opts=(items,value,label,selected)=>items.map(x=>`<option value="${E(value(x))}" ${value(x)===selected?'selected':''}>${E(label(x))}</option>`).join('');
