function toast(s){const notice=$('#toast');clearTimeout(toast.timer);notice.replaceChildren();const text=document.createElement('span');text.textContent=s;const close=document.createElement('button');close.type='button';close.className='notice-close';close.textContent='닫기';close.setAttribute('aria-label','안내 닫기');close.onclick=()=>{clearTimeout(toast.timer);notice.style.display='none'};notice.append(text,close);notice.style.display='flex';if(modal.open){notice.classList.add('dialog-notice');notice.setAttribute('role','alert');notice.setAttribute('aria-live','assertive');modal.prepend(notice);notice.tabIndex=-1;notice.focus({preventScroll:true});notice.scrollIntoView({block:'nearest'});}else{document.body.append(notice);notice.classList.remove('dialog-notice');notice.setAttribute('role','status');notice.setAttribute('aria-live','polite');toast.timer=setTimeout(()=>notice.style.display='none',6000)}}
modal.addEventListener('close',()=>{if(modal.open)return;const notice=$('#toast');if(!notice)return;document.body.append(notice);notice.classList.remove('dialog-notice');notice.setAttribute('role','status');notice.setAttribute('aria-live','polite');clearTimeout(toast.timer);toast.timer=setTimeout(()=>notice.style.display='none',6000)});

async function commit(action,fn,options={}){
 if(saving)throw Error('저장 중입니다. 잠시 후 다시 시도해 주세요.');
 if(!cloud){const persisted=localStorage.getItem(demoKey);if(persisted&&JSON.parse(persisted).revision!==d.revision)throw Error('다른 탭에서 수정되었습니다. 새로고침 후 다시 편집해 주세요.');}
 const next=M.transact(d,role==='admin'?'원장(시연)':role==='teacher'?teacher(teacherId)?.name:student(studentId)?.name,action,fn);
 saving=true;
 try{
  if(cloud){const response=await fetch('/api/sandbox',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:next,expectedRevision:d.revision})});if(!response.ok){if(response.status===409)throw Error('다른 기기에서 수정되었습니다. 새로고침한 뒤 다시 편집해 주세요.');throw Error('서버에 저장하지 못했습니다. 연결을 확인하고 다시 시도해 주세요.');}}
  try{if(!cloud)localStorage.setItem(demoKey,JSON.stringify(next))}catch{if(!cloud)throw Error('브라우저 저장 공간이 부족합니다. 음원 크기를 줄여 주세요.');}
  d=next;dailyInvalidateSaved();if(options.render!==false){dirty=false;render()}if(!options.quiet)toast(cloud?'테스트 서버에 저장되었습니다.':'저장되었습니다 · 이 브라우저의 테스트 데이터');
 }finally{saving=false}
}
function adminOnly(){if(role!=='admin')throw Error('원장님 시연 모드에서 사용할 수 있습니다.')}
function staffOnly(){if(!['admin','teacher'].includes(role))throw Error('교직원 시연 모드에서 확인해 주세요.')}
function scope(id){staffOnly();if(!visibleStudents().some(s=>s.id===id))throw Error('담당 학생만 확인할 수 있습니다.')}
function open(title,html,submit,label='저장'){dirty=false;const notice=$('#toast');clearTimeout(toast.timer);document.body.append(notice);notice.style.display='none';notice.classList.remove('dialog-notice');modal.innerHTML=`<form id="editor"><div class="row between"><h2>${E(title)}</h2>${btn('닫기','close','quiet','type="button"')}</div>${html}<div class="actions">${btn('취소','close','secondary','type="button"')}<button type="submit">${E(label)}</button></div></form>`;modal.showModal();$('#editor').onsubmit=async e=>{e.preventDefault();try{await submit(new FormData(e.currentTarget));modal.close()}catch(err){toast(err.message)}};$('#editor').addEventListener('input',e=>{if(!['unit','copyFrom'].includes(e.target.name))dirty=true})}
on('close',()=>{if(!dirty||confirm('저장하지 않은 내용을 닫을까요?')){dirty=false;modal.close()}});modal.addEventListener('cancel',e=>{if(dirty&&!confirm('저장하지 않은 내용을 닫을까요?'))e.preventDefault()});
function head(eyebrow,title,desc,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${desc}</p></div><div class="row">${buttons}</div></div>`}
const nav=[['daily','☑','오늘 빠른 입력'],['dashboard','◫','대시보드'],['students','♧','학생 관리'],['learning','▤','학습·진도'],['books','▥','교재·Unit'],['attendance','◷','출결 관리'],['teachers','♧','교사 관리'],['tuition','₩','수강료'],['notifications','✉','학부모 알림'],['reports','▧','월간 리포트'],['announcements','📣','공지사항'],['settings','⚙','테스트 설정']];
function render(){
 root.className=role==='student'?'student-mode':'';
 const allowed=role==='admin'?nav:role==='teacher'?nav.filter(x=>!['tuition','teachers','settings'].includes(x[0])):(actualAccess?.role==='student'?[['student','▤','내 학습']]:[['student','▤','내 학습'],['kiosk','◷','태블릿 출결']]);if(!allowed.some(x=>x[0]===view))view=allowed[0][0];
 root.innerHTML=`<aside class="sidebar"><div class="brand">THE BOM<small>ACADEMY OS</small></div><div class="side-label">WORKSPACE</div><nav aria-label="주 메뉴">${allowed.map(([id,icon,name])=>`<button data-action="nav" data-id="${id}" class="${view===id?'active':''}"><span class="navicon">${icon}</span>${name}</button>`).join('')}</nav><div class="side-bottom">더봄어학원<br><span class="muted">Play · Learn · Bloom</span><p style="margin-top:12px">통합 관리 · 테스트 워크스페이스</p></div></aside><main class="main"><header class="topbar"><span class="crumb">더봄어학원 &nbsp; / &nbsp; ${E(allowed.find(x=>x[0]===view)?.[2])}</span><div class="role-control">${badge('SANDBOX','amber')}<label for="role" class="muted">화면 시연</label><select id="role" data-change="role"><option value="admin" ${role==='admin'?'selected':''}>원장님</option><option value="teacher" ${role==='teacher'?'selected':''}>선생님</option><option value="student" ${role==='student'?'selected':''}>학생</option></select>${role==='teacher'?`<select aria-label="시연 교사" data-change="teacher">${opts(d.teachers.filter(x=>x.active),x=>x.id,x=>x.name,teacherId)}</select>`:''}${actualAccess&&actualAccess.role!=='admin'?`<span class="badge">실제 ${actualAccess.role==='teacher'?'교사':'학생'} 계정</span>`:''}</div></header><div class="test-banner"><span><b>독립 테스트 환경</b> · 운영 학생 DB 분리 · ${cloud?'비공개 테스트 서버에 저장':'현재 브라우저에 저장'}</span><span>운영 DB 연결 없음 / 알림·결제 실제 전송 없음</span></div><div class="content" id="content"></div></main>`;
 const views={daily:dailyView,dashboard,students,learning,books,attendance,teachers,tuition,notifications,reports,announcements,settings,student:studentPage,kiosk};if(actualAccess&&actualAccess.role!=='admin')root.querySelectorAll('#role,[for="role"],[data-change="teacher"]').forEach(el=>el.hidden=true);$('#content').innerHTML=views[view]();if(actualAccess&&actualAccess.role!=='admin'){root.querySelectorAll('.demo-student').forEach(el=>el.hidden=true);root.querySelectorAll('[data-action^="student-edit:"],[data-action^="assign:"],[data-action="kiosk-demo"],[data-action="student-demo"]').forEach(el=>el.hidden=true);}if($('#daily-summary')){dailyRefreshSummary();dailyApplyFilter()}
 if(storageProblem)toast('저장된 데이터를 읽을 수 없어 임시 시연 화면을 표시합니다. 테스트 설정에서 초기화할 수 있어요.');
}
on('nav',el=>{view=el.dataset.id;if(view==='books')labTab='books';if(view==='learning')labTab='overview';render()});
function dashboardContent(){const sts=visibleStudents().filter(x=>x.active),as=visibleAssignments(),attendance=d.attendance.filter(x=>x.date===M.today()&&sts.some(s=>s.id===x.studentId)),waiting=as.flatMap(a=>Array.from({length:M.book(d,a.bookId).units-a.start+1},(_,i)=>i+a.start).map(u=>({a,u,s:M.effectiveSteps(d,a,u),p:M.progress(d,a,u)}))).filter(x=>x.s.length&&x.s.every(s=>x.p?.checked.includes(s.id))&&!x.p.approvedAt);const bills=d.invoices.filter(i=>i.month===M.month()&&!i.cancelled);return head('TODAY AT THE BOM','아이들의 성장이 모이는 곳',new Date().toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',year:'numeric',month:'long',day:'numeric',weekday:'long'}),btn('학생 화면 시연','student-demo')+btn('태블릿 출결','kiosk-demo',''))+`<div class="hero"><div><div class="eyebrow">PLAY · LEARN · BLOOM</div><h2>오늘도, 한 걸음 더 자라는 하루.</h2><p class="muted">학습부터 출결까지 오늘의 흐름을 한눈에 확인하세요.</p></div><div class="mark">❋</div></div><div class="metrics"><div class="metric"><div class="label">재원 학생</div><div class="num">${sts.length}<small>명</small></div><div class="foot">${role==='teacher'?'담당 학생 기준':'가상 학생 · 실데이터 미사용'}</div></div><div class="metric"><div class="label">오늘 등원</div><div class="num">${attendance.filter(x=>x.in).length}<small>/ ${sts.length}명</small></div><div class="foot">하원 ${attendance.filter(x=>x.out).length}명</div></div><div class="metric"><div class="label">학습 확인 대기</div><div class="num">${waiting.length}<small>건</small></div><div class="foot">모든 단계를 마친 Unit</div></div><div class="metric"><div class="label">${role==='admin'?'이번 달 미수금':'진행 중인 교재 배정'}</div><div class="num">${role==='admin'?money(bills.reduce((s,i)=>s+i.amount-M.paid(i),0)):as.length}</div><div class="foot">${role==='admin'?'부분 수납 포함 · 테스트 장부':'담당 학생 기준'}</div></div></div><div class="columns"><div class="card"><div class="row between"><h2>학생별 학습 현황</h2>${btn('전체 보기 →','go-learning','quiet')}</div>${learningTable(as)}</div><div><div class="card"><h2>선생님 확인을 기다려요</h2>${waiting.length?waiting.map(({a,u})=>`<div class="activity row between"><div><b>${E(student(a.studentId).name)}</b><div class="muted">${E(M.book(d,a.bookId).title)} · Unit ${u}</div></div>${btn('확인',`approve:${a.id}:${u}`)}</div>`).join(''):'<div class="empty">대기 중인 Unit이 없습니다.<br>학생 화면에서 단계를 완료해 보세요.</div>'}</div><div class="card"><h2>최근 활동</h2>${d.audit.slice(-5).reverse().map(x=>`<div class="activity"><span class="dot"></span>${E(x.action)}<div class="muted">${E(x.actor)} · ${new Date(x.at).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit'})}</div></div>`).join('')||'<p class="muted">테스트를 시작하면 활동이 기록됩니다.</p>'}</div></div></div>`}
on('go-learning',()=>{view='learning';labTab='overview';render()});on('student-demo',()=>{role='student';view='student';render()});on('kiosk-demo',()=>{view='kiosk';role='student';render()});
function dashboard(){return noticeOverview()+dashboardContent()}
function learningTable(as){return `<div class="table-wrap"><table><thead><tr><th>학생 / 교재</th><th>다음 Unit</th><th>전체 진행률</th><th></th></tr></thead><tbody>${as.map(a=>{const s=M.stats(d,a),u=M.nextUnit(d,a);return `<tr><td><b>${E(student(a.studentId)?.name)}</b><div class="muted">${E(M.book(d,a.bookId)?.title)}</div></td><td>${u}</td><td>${s.percent}%${bar(s.percent)}<span class="muted">${s.done}/${s.total}단계</span></td><td>${btn('자세히',`detail:${a.id}`,'quiet')}</td></tr>`}).join('')}</tbody></table>${!as.length?'<div class="empty">배정된 교재가 없습니다.</div>':''}</div>`}
function students(){const items=visibleStudents().filter(x=>(studentListStatus==='withdrawn'?!x.active:x.active)&&(x.name+' '+x.grade).includes(studentQuery));return head('STUDENTS','학생 관리','학생의 담당 교사, 요일별 교재와 학습 메모를 관리해요.',role==='admin'?btn('+ 학생 등록','add-student',''):'')+`<div class="card"><div class="row between"><div class="row">${btn(`재원생 (${visibleStudents().filter(s=>s.active).length}명)`,'students-active',studentListStatus==='active'?'':'secondary')}${btn(`퇴원생 (${visibleStudents().filter(s=>!s.active).length}명)`,'students-withdrawn',studentListStatus==='withdrawn'?'':'secondary')}</div><h2>${studentListStatus==='withdrawn'?'퇴원생 목록':'재원생 목록'} <span class="muted">${items.length}명</span></h2><input class="search" aria-label="학생 검색" placeholder="이름 또는 학년 검색" value="${E(studentQuery)}" data-input="student-search"></div><div class="table-wrap"><table><thead><tr><th>학생</th><th>담당 교사</th><th>수업시간표</th><th>보호자 연락처</th><th>배정 교재</th><th>상태</th><th></th></tr></thead><tbody>${items.map(s=>`<tr><td><div class="person"><div class="avatar">${E(s.grade)}</div><div><b>${E(s.name)}</b><div class="muted">시연 출결번호 ${E(s.pin)}</div></div></div></td><td>${E(teacher(s.teacherId)?.name||'미지정')}</td><td style="white-space:normal;min-width:180px">${E(studentScheduleText(s))}</td><td>${E(s.guardianPhone||'미등록')}</td><td>${d.assignments.filter(a=>a.studentId===s.id&&!a.archived).length}권</td><td>${badge(s.active?'재원':'퇴원',s.active?'':'amber')}</td><td>${btn('학생 정보',`student-edit:${s.id}`,'quiet')} ${s.active?btn('학습 배정',`assign:${s.id}`,'quiet'):btn('보관 기록',`student-history:${s.id}`,'quiet')} ${role==='admin'?btn(s.active?'퇴원 처리':'재등록',`student-status:${s.id}`,'quiet'):''}</td></tr>`).join('')}</tbody></table></div></div>`}
on('add-student',()=>editStudent());

function assign(id){scope(id);if(role!=='admin')throw Error('교재 배정은 원장님 시연 모드에서 가능합니다.');open(student(id).name+' · 교재 배정',`${select('교재','bookId',opts(d.books.filter(x=>!x.archived),x=>x.id,x=>x.title))}${f('시작 Unit','start',1,'number','min="1" max="200" required')}<div class="field"><label>학습 요일</label><div class="week">${['일','월','화','수','목','금','토'].map((x,i)=>`<label><input type="checkbox" name="days" value="${i}">${x}</label>`).join('')}</div></div>`,v=>{const bookId=v.get('bookId'),start=Number(v.get('start'));if(!Number.isInteger(start)||start<1||start>M.book(d,bookId)?.units)throw Error('시작 Unit을 확인해 주세요.');if(d.assignments.some(a=>a.studentId===id&&a.bookId===bookId&&!a.archived))throw Error('이미 배정된 교재입니다.');return commit('학생 교재 배정',n=>n.assignments.push({id:M.uid(),studentId:id,bookId,start,days:v.getAll('days').map(Number),customSteps:null,archived:false}))})}
function learning(){return labView()}
on('assign-first',()=>{if(!visibleStudents().length)throw Error('학생을 먼저 등록해 주세요.');assign(visibleStudents()[0].id)});
function detail(id){const a=d.assignments.find(x=>x.id===id);scope(a.studentId);open(student(a.studentId).name+' · '+M.book(d,a.bookId).title,`<div class="note">요일과 시작 Unit을 수정해도 기존 완료 기록을 지우지 않습니다.</div>${f('시작 Unit','start',a.start,'number',`min="1" max="${M.book(d,a.bookId).units}" required`)}<div class="week">${['일','월','화','수','목','금','토'].map((day,i)=>`<label><input name="days" type="checkbox" value="${i}" ${a.days.includes(i)?'checked':''}>${day}</label>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Unit</th><th>학습</th><th>선생님 확인</th></tr></thead><tbody>${Array.from({length:M.book(d,a.bookId).units-a.start+1},(_,i)=>i+a.start).map(u=>{const s=M.effectiveSteps(d,a,u),p=M.progress(d,a,u),done=s.filter(x=>p?.checked.includes(x.id)).length;return `<tr><td>${u}</td><td>${done}/${s.length}단계</td><td>${p?.approvedAt?badge('확인 완료'):btn('최종 확인',`approve:${a.id}:${u}`,'secondary',`type="button" ${!s.length||done!==s.length?'disabled':''}`)}</td></tr>`}).join('')}</tbody></table></div>${btn('학생별 맞춤 과정',`individual:${id}`,'secondary','type="button"')} ${role==='admin'?btn('배정 해제 (기록 보존)',`unassign:${id}`,'danger','type="button"'):''}`,v=>{const start=Number(v.get('start'));if(!Number.isInteger(start)||start<1||start>M.book(d,a.bookId).units)throw Error('시작 Unit을 확인해 주세요.');if(start>a.start&&d.progress.some(p=>p.assignmentId===id&&p.unit<start))throw Error('학습 기록이 있는 Unit을 범위 밖으로 제외할 수 없습니다.');return commit('요일별 학습 계획 수정',n=>Object.assign(n.assignments.find(x=>x.id===id),{start,days:v.getAll('days').map(Number)}))})}
function books(){return labView()}
on('add-book',()=>editBook());
function editBook(id){adminOnly();const b=M.book(d,id)||{title:'',category:'미분류',units:12};open(id?'교재 정보':'새 교재 등록',`${f('교재명','title',b.title,'text','required maxlength="100"')}${f('카테고리','category',b.category,'text','required maxlength="50"')}${f('Unit 개수','units',b.units,'number','required min="1" max="200"')}${id?select('사용 상태','archived',`<option value="false" ${!b.archived?'selected':''}>사용 중</option><option value="true" ${b.archived?'selected':''}>보관 (기록 유지)</option>`):'<p class="muted">등록 후 학습 과정을 설정해 주세요.</p>'}`,v=>{const units=Number(v.get('units')),title=v.get('title').trim();if(!title||!Number.isInteger(units)||units<1||units>200)throw Error('교재명과 Unit 개수를 확인해 주세요.');if(id&&units<b.units)throw Error('Unit 축소는 기록 보호를 위해 제한됩니다. 교재를 보관하거나 새 교재를 등록해 주세요.');return commit(id?'교재 정보 수정':'교재 등록',n=>{const change={title,category:v.get('category').trim(),units,archived:v.get('archived')==='true'};if(id)Object.assign(n.books.find(x=>x.id===id),change);else n.books.push({id:M.uid(),...change,steps:[]})})})}
function stepsEditor(id,u=0){uploaded={};draftBook=id;draftUnit=u;const b=M.book(d,id);draftSteps=M.clone(u?d.unitSteps.find(x=>x.bookId===id&&x.unit===u)?.steps??b.steps:b.steps);open(b.title+' · 학습 과정',`${select('편집할 과정','unit',`<option value="0" ${u===0?'selected':''}>교재 기본 과정</option>`+Array.from({length:b.units},(_,i)=>`<option value="${i+1}" ${u===i+1?'selected':''}>Unit ${i+1}${d.unitSteps.some(x=>x.bookId===id&&x.unit===i+1)?' · 맞춤 과정':''}</option>`).join(''))}<div class="note">${u?'이 Unit만 저장됩니다. 별도 설정이 없으면 교재 기본 과정을 사용해요.':'모든 Unit의 기본 과정입니다. Unit별 설정은 그대로 유지됩니다.'} 기존 기록이 있으면 설명·페이지만 수정할 수 있어요.</div><div class="row">${select('복사할 과정','copyFrom',`<option value="0">교재 기본 과정</option>`+Array.from({length:b.units},(_,i)=>`<option value="${i+1}">Unit ${i+1}</option>`).join(''))}${btn('복사해서 편집','copy-steps','secondary','type="button"')}${u?btn('기본 과정으로 복원','restore-steps','secondary','type="button"'):''}</div>${role==='admin'?crossBookStepsHTML(id):''}<div id="step-rows"></div>${role==='admin'?btn('+ 단계 추가','add-step','secondary','type="button"'):'<p class="muted">학습 과정 편집은 원장님 모드에서 가능합니다.</p>'}${u?`<hr><h3>Unit별 학습 자료</h3><div class="note">음원은 테스트 데이터에 저장됩니다. 온라인 업로드는 파일당 20MB, 브라우저 시연은 1.5MB 이내입니다. 원본 파일은 별도로 보관하고, 온라인 저장 용량을 확인해 주세요.</div>${materialFields(id,u)}`:''}`,v=>{adminOnly();collectSteps();return commit('교재 학습 과정 수정',n=>{M.saveSteps(n,id,draftUnit,draftSteps);if(draftUnit)saveMaterial(n,id,draftUnit,v)})},role==='admin'?'과정 저장':'닫기');drawSteps();$('[name="unit"]').onchange=e=>{collectSteps();if(dirty&&!confirm('저장하지 않은 변경을 버리고 다른 Unit을 열까요?')){e.target.value=draftUnit;return}modal.close();stepsEditor(id,Number(e.target.value))}}
function collectSteps(){draftSteps=[...modal.querySelectorAll('.stepedit')].map(el=>({...draftSteps[Number(el.dataset.index)],name:el.querySelector('[data-step="name"]').value.trim(),desc:el.querySelector('[data-step="desc"]').value.trim(),page:el.querySelector('[data-step="page"]').value.trim(),kind:el.querySelector('[data-step="kind"]').value}))}
function drawSteps(){const target=$('#step-rows');if(!target)return;target.innerHTML=draftSteps.map((s,i)=>`<div class="stepedit" data-index="${i}"><div class="row between"><span class="number">STEP ${String(i+1).padStart(2,'0')}</span><div>${btn('↑',`step-up:${i}`,'quiet',`type="button" ${i===0?'disabled':''}`)}${btn('↓',`step-down:${i}`,'quiet',`type="button" ${i===draftSteps.length-1?'disabled':''}`)}${btn('삭제',`step-delete:${i}`,'quiet','type="button"')}</div></div><div class="field"><label for="step-name-${i}">단계 이름</label><input id="step-name-${i}" data-step="name" value="${E(s.name)}" required maxlength="100"></div><div class="field"><label for="step-desc-${i}">학습 안내</label><textarea id="step-desc-${i}" data-step="desc">${E(s.desc)}</textarea></div><div class="formgrid"><div class="field"><label for="step-page-${i}">페이지</label><input id="step-page-${i}" data-step="page" value="${E(s.page)}"></div><div class="field"><label for="step-kind-${i}">연결 유형</label><select id="step-kind-${i}" data-step="kind">${opts([{v:'',n:'일반 학습'},{v:'word',n:'단어 음원'},{v:'reading',n:'리딩 음원'},{v:'classcard',n:'클래스카드 앱'}],x=>x.v,x=>x.n,s.kind||'')}</select></div></div></div>`).join('')||'<p class="empty">단계를 추가해 학습 과정을 구성해 주세요.</p>'}
on('add-step',()=>{adminOnly();collectSteps();draftSteps.push({id:M.uid(),name:'',desc:'',page:'',kind:''});dirty=true;drawSteps()});
on('copy-steps',()=>{adminOnly();collectSteps();const from=Number($('[name="copyFrom"]').value),b=M.book(d,draftBook);draftSteps=M.clone(from?d.unitSteps.find(x=>x.bookId===draftBook&&x.unit===from)?.steps??b.steps:b.steps);dirty=true;drawSteps()});
on('restore-steps',async()=>{adminOnly();const b=M.book(d,draftBook);const temp=M.clone(d);M.saveSteps(temp,draftBook,draftUnit,b.steps);if(!confirm('이 Unit의 개별 설정을 해제하고 교재 기본 과정을 사용할까요?'))return;await commit('Unit 기본 과정 복원',n=>n.unitSteps=n.unitSteps.filter(x=>!(x.bookId===draftBook&&x.unit===draftUnit)));modal.close();stepsEditor(draftBook,draftUnit)});
function audioPlayer(source,label){return `<div class="audio-resource"><audio controls preload="metadata" src="${E(source)}" aria-label="${E(label)}"></audio><p class="audio-status muted" role="status">재생 버튼을 눌러 음원을 확인해 주세요.</p>${source.startsWith('https:')?`<a href="${E(source)}" target="_blank" rel="noopener noreferrer">음원 주소 새 창에서 열기 ↗</a>`:''}</div>`}
function materialFields(id,u){const m=d.materials.find(x=>x.bookId===id&&x.unit===u)||{};return `<p class="note">${cloud?'음원 파일은 전용 저장소에 보관하고 Unit에는 연결 정보만 저장합니다. 파일당 20MB, 테스트 저장량 100MB 제한입니다.':'브라우저 시연 업로드는 파일당 1.5MB 이내입니다.'} MP3·WAV 등의 직접 음원 주소도 사용할 수 있습니다. 출판사 자료실 주소는 아래 ‘자료실 페이지’에 넣으세요. GitHub 파일 보기 주소는 직접 음원 주소로 변환합니다.</p>${['word','reading'].map(kind=>`<h3>${kind==='word'?'단어':'리딩'} 음원</h3>${f('직접 음원 HTTPS 주소',kind+'Url',m[kind+'Url']||'','text',`inputmode="url" data-material-url="${kind}"`)}${f('자료실 페이지 HTTPS 주소 (선택)',kind+'PageUrl',m[kind+'PageUrl']||'','url')}<div class="field"><label for="audio-${kind}">${kind==='word'?'단어':'리딩'} 음원 파일 업로드 (${cloud?'20MB':'1.5MB'} 이내)</label><input type="file" id="audio-${kind}" accept="audio/*,.mp3,.wav,.m4a,.ogg,.aac,.webm" data-audio="${kind}Url"></div><div id="preview-${kind}">${materialPreview(m,kind)}</div>${btn('업로드 파일 제거', 'audio-remove-'+kind,'quiet','type="button"')}`).join('')}${f('클래스카드 HTTPS 링크 (없으면 앱 실행 버튼)','classcardUrl',m.classcardUrl||'','url')}<p class="muted" id="upload-status">변경 후 ‘자료 저장’을 눌러야 학생 화면에 반영됩니다.</p>`}
function materialPreview(m,kind){const source=m[kind+'Data']||m[kind+'Url'];return source?audioPlayer(source,kind==='word'?'단어 음원 미리듣기':'리딩 음원 미리듣기'):'<p class="muted">직접 재생 음원이 없습니다.</p>'}
let uploaded={},audioUploadBusy=0;function saveMaterial(n,id,u,v){if(audioUploadBusy)throw Error('음원을 읽고 있습니다. 잠시 후 저장해 주세요.');return M.saveMaterial(n,id,u,Object.fromEntries(['wordUrl','readingUrl','wordPageUrl','readingPageUrl','classcardUrl'].map(k=>[k,v.get(k)?.trim()||''])),uploaded)}

function attendance(){return attendancePreparation()+attendanceContent()}
function attendanceContent(){const rows=d.attendance.filter(x=>x.date===attDate&&visibleStudents().some(s=>s.id===x.studentId));return head('ATTENDANCE','출결 관리','등원·하원을 기록하고, 누락된 출결을 확인해요.',btn('태블릿 화면 시연','kiosk-demo')+btn('CSV 내려받기','attendance-csv'))+`<div class="card"><div class="row between"><h2>일별 출결</h2><input aria-label="출결 날짜" type="date" value="${attDate}" data-change="attDate"></div><div class="table-wrap"><table><thead><tr><th>학생</th><th>상태</th><th>등원</th><th>하원</th><th>처리</th></tr></thead><tbody>${visibleStudents().filter(s=>s.active).map(s=>{const r=rows.find(x=>x.studentId===s.id);return `<tr><td><b>${E(s.name)}</b></td><td>${badge(r?.status||'미기록',r?.status==='결석'?'red':r?'':'amber')}</td><td>${time(r?.in)}</td><td>${time(r?.out)}</td><td><div class="row">${btn('등원',`attend:${s.id}:in`,'secondary',r?.in?'disabled':'')}${btn('하원',`attend:${s.id}:out`,'secondary',!r?.in||r?.out?'disabled':'')}${btn('수정',`attendance-edit:${s.id}`,'quiet')}</div></td></tr>`}).join('')}</tbody></table></div></div><p class="muted">등·하원 시각은 한국 시간 기준입니다. 이 테스트에서는 학부모에게 알림이 전송되지 않습니다.</p>`}
const time=x=>x?new Date(x).toLocaleTimeString('ko-KR',{timeZone:'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}):'—';
function attendanceEdit(id){scope(id);const r=d.attendance.find(x=>x.studentId===id&&x.date===attDate);open(student(id).name+' · 출결 수정',`${select('상태','status',opts(['출석','지각','결석','인정결석'],x=>x,x=>x,r?.status||'출석'))}${f('등원 시각 (한국 시간)','in',r?.in?time(r.in):'','time')}${f('하원 시각 (한국 시간)','out',r?.out?time(r.out):'','time')}${area('수정 사유','reason',r?.reason||'')}`,v=>{const toISO=x=>x?new Date(attDate+'T'+x+':00+09:00').toISOString():null;const input=toISO(v.get('in')),out=toISO(v.get('out'));if(out&&(!input||out<input))throw Error('하원 시각은 등원 이후여야 합니다.');if(v.get('status')==='출석'&&!input)throw Error('출석 처리에는 등원 시각이 필요합니다.');if(!v.get('reason').trim())throw Error('출결 수정 사유를 입력해 주세요.');return commit('출결 수동 수정',n=>{let row=n.attendance.find(x=>x.studentId===id&&x.date===attDate);if(!row){row={id:M.uid(),studentId:id,date:attDate};n.attendance.push(row)}Object.assign(row,{status:v.get('status'),in:input,out,reason:v.get('reason').trim()})})})}
function kiosk(){return head('ATTENDANCE KIOSK','태블릿 출결','테스트 번호로 등·하원 동작을 확인해 보세요.')+`<div class="card kiosk"><span class="eyebrow">WELCOME TO THE BOM</span><h1>반가워요, 오늘도 🌱</h1><p class="muted">내 출결번호 4자리를 눌러 주세요.</p><div class="field"><label for="kiosk-pin">출결번호</label><input id="kiosk-pin" inputmode="numeric" maxlength="4" autocomplete="off" aria-label="출결번호" placeholder="••••"></div><div class="keys">${['1','2','3','4','5','6','7','8','9','지우기','0','←'].map(x=>btn(x,`key:${x}`)).join('')}</div><div class="row" style="justify-content:center">${btn('등원하기','kiosk-in','')}${btn('하원하기','kiosk-out')}</div><div class="note" style="margin-top:20px">시연 번호: 봄이 1001 · 새싹 1002 · 나무 1003<br>이 화면은 인증 기능을 대신하지 않는 테스트 화면입니다.</div></div>`}
async function kioskAttendance(action){const s=d.students.find(x=>x.active&&x.pin===$('#kiosk-pin').value);if(!s)throw Error('번호를 다시 확인해 주세요.');const name=s.name;await commit('태블릿 '+(action==='in'?'등원':'하원'),n=>M.attend(n,s.id,M.today(),action));toast(name+' · '+(action==='in'?'등원':'하원')+' 완료! (테스트 기록)')}
on('kiosk-in',()=>kioskAttendance('in'));on('kiosk-out',()=>kioskAttendance('out'));
function teachers(){adminOnly();return head('TEAM','교사 관리','담당 학생과 수업 분야를 한곳에서 관리해요.',btn('+ 교사 등록','add-teacher',''))+`<div class="row" style="margin-bottom:18px">${btn(`재직 교사 (${d.teachers.filter(t=>t.active).length}명)`,'teachers-active',teacherListStatus==='active'?'':'secondary')}${btn(`퇴사 교사 (${d.teachers.filter(t=>!t.active).length}명)`,'teachers-retired',teacherListStatus==='retired'?'':'secondary')}</div><div class="grid">${d.teachers.filter(t=>teacherListStatus==='retired'?!t.active:t.active).map(t=>`<div class="card"><div class="row between"><div class="avatar">T</div>${badge(t.active?'재직':'퇴사',t.active?'':'amber')}</div><h2 style="margin-top:18px">${E(t.name)}</h2><p class="muted">${E(t.subject)}</p><p>담당 학생 <b>${d.students.filter(x=>x.teacherId===t.id&&x.active).length}명</b></p><p class="muted">${d.students.filter(x=>x.teacherId===t.id).map(s=>E(s.name)).join(' · ')||'담당 학생이 없습니다.'}</p>${btn('교사 정보 수정',`teacher-edit:${t.id}`)} ${btn(t.active?'퇴사 처리':'재직 복원',`teacher-status:${t.id}`)}</div>`).join('')}</div><div class="note">퇴사 교사는 신규 담당 교사 선택과 실제 교사 계정 접근에서 제외됩니다. 기존 지도 기록은 보존됩니다.</div>`}
on('add-teacher',()=>editTeacher());function editTeacher(id){adminOnly();const t=teacher(id)||{name:'',subject:'',active:true};open(id?'교사 정보 수정':'가상 교사 등록',`${f('교사 이름','name',t.name,'text','required maxlength="40"')}${f('수업 분야','subject',t.subject,'text','required maxlength="60"')}${id?select('상태','active',`<option value="true" ${t.active?'selected':''}>재직</option><option value="false" ${t.active?'':'selected'}>퇴사</option>`):''}`,v=>{if(v.get('active')==='false'&&d.students.some(x=>x.teacherId===id&&x.active))throw Error('재원 학생의 담당 교사를 변경한 뒤 퇴사 처리해 주세요.');const item={id:id||M.uid(),name:v.get('name').trim(),subject:v.get('subject').trim(),active:v.get('active')!=='false'};if(!item.name)throw Error('교사 이름을 입력해 주세요.');return commit('교사 정보 저장',n=>{if(id)Object.assign(n.teachers.find(x=>x.id===id),item);else n.teachers.push(item)})})}
function tuition(){adminOnly();const bills=d.invoices.filter(x=>x.month===invoiceMonth),live=bills.filter(x=>!x.cancelled),total=live.reduce((s,i)=>s+i.amount,0),received=live.reduce((s,i)=>s+M.paid(i),0);return head('BILLING','수강료 관리','청구와 부분 수납 내역을 관리하는 테스트 장부예요.',btn('CSV 내려받기','tuition-csv')+btn('+ 수강료 청구','add-invoice',''))+`<div class="row"><label for="bill-month">청구 월</label><input type="month" id="bill-month" value="${invoiceMonth}" data-change="invoiceMonth"></div><div class="metrics"><div class="metric"><div class="label">청구 합계</div><div class="num">${money(total)}</div></div><div class="metric"><div class="label">수납 합계</div><div class="num">${money(received)}</div></div><div class="metric"><div class="label">미수금</div><div class="num">${money(total-received)}</div></div><div class="metric"><div class="label">미납·부분 수납</div><div class="num">${live.filter(x=>M.paid(x)<x.amount).length}<small>건</small></div></div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>학생</th><th>청구액 / 수납액</th><th>납부 기한</th><th>상태</th><th></th></tr></thead><tbody>${bills.map(i=>`<tr><td><b>${E(student(i.studentId)?.name)}</b><div class="muted">${E(i.memo)}</div></td><td class="balance">${money(i.amount)}<div class="muted">수납 ${money(M.paid(i))}</div></td><td>${E(i.due)}</td><td>${badge(i.cancelled?'취소':M.paid(i)===i.amount?'수납 완료':M.paid(i)?'부분 수납':'미납',i.cancelled?'':M.paid(i)===i.amount?'':'amber')}</td><td>${btn('내역·수납',`invoice:${i.id}`,'quiet')}</td></tr>`).join('')}</tbody></table>${!bills.length?'<div class="empty">이 월의 청구 내역이 없습니다.</div>':''}</div></div>${tuitionNoticesHTML()}${billingSettingsHTML()}<div class="note">실제 결제 승인·카드 취소·결제선생 API와 연결되지 않은 장부입니다. 실제 결제는 발생하지 않습니다.</div>`}
on('add-invoice',()=>{adminOnly();open('수강료 청구 등록',`${select('학생','studentId',opts(d.students.filter(x=>x.active),x=>x.id,x=>x.name))}<div class="formgrid">${f('청구 월','month',invoiceMonth,'month','required')}${f('청구 금액 (원)','amount',260000,'number','required min="1" max="10000000" step="1"')}${f('납부 기한','due',invoiceMonth+'-05','date','required')}</div>${f('메모','memo','','text','maxlength="100"')}`,v=>{const amount=Number(v.get('amount'));if(!v.get('studentId')||!Number.isInteger(amount)||amount<1||amount>10000000)throw Error('학생과 금액을 확인해 주세요.');if(d.invoices.some(x=>x.studentId===v.get('studentId')&&x.month===v.get('month')&&!x.cancelled))throw Error('이 학생은 해당 월에 청구 내역이 있습니다. 중복 청구를 막았습니다.');return commit('수강료 청구 등록',n=>n.invoices.push({id:M.uid(),studentId:v.get('studentId'),month:v.get('month'),amount,due:v.get('due'),memo:v.get('memo').trim(),payments:[],cancelled:false}))})});
function invoiceDetail(id){adminOnly();const i=d.invoices.find(x=>x.id===id);open(student(i.studentId).name+' · '+i.month+' 수강료',`<div class="note">청구 ${money(i.amount)} · 수납 ${money(M.paid(i))} · 남은 금액 ${money(i.amount-M.paid(i))}</div>${i.payments.map(p=>`<div class="activity row between"><span>${E(p.date)} · ${E(p.method)}</span><b>${money(p.amount)}</b></div>`).join('')||'<p class="muted">수납 내역이 없습니다.</p>'}${!i.cancelled&&M.paid(i)<i.amount?`<hr><h3>수납 기록 추가</h3><div class="formgrid">${f('수납 금액 (원)','amount',i.amount-M.paid(i),'number',`min="1" max="${i.amount-M.paid(i)}" step="1" required`)}${f('수납일','date',M.today(),'date','required')}${select('수납 방법','method',opts(['카드','계좌이체','현금','광양사랑카드'],x=>x,x=>x))}</div>`:''}${!i.cancelled&&!M.paid(i)?btn('청구 취소 (기록 유지)',`cancel-invoice:${id}`,'danger','type="button"'):''}`,v=>{if(v.has('amount'))return commit('수강료 수납 기록',n=>M.addPayment(n,id,Number(v.get('amount')),v.get('date'),v.get('method')))},!i.cancelled&&M.paid(i)<i.amount?'수납 기록 저장':'닫기')}
function notifications(){const items=d.notifications.filter(x=>visibleStudents().some(s=>s.id===x.studentId));return head('PARENT COMMUNICATION','학부모 알림','학생별 안내 문구를 준비하고 검토한 뒤 복사해요.',btn('+ 알림 작성','add-notification',''))+`<div class="note">카카오 알림톡·채널톡 연결 전입니다. 여기서는 초안 작성·복사만 가능하며, 전송 완료 상태를 만들지 않습니다.</div><div class="grid">${items.map(x=>`<div class="card"><div class="row between"><b>${E(student(x.studentId)?.name)}</b>${badge(x.status==='reviewed'?'검토 완료':'초안','amber')}</div><p class="muted">수신 보호자: ${E(student(x.studentId)?.guardianName||'미등록')} · ${E(student(x.studentId)?.guardianPhone||'연락처 미등록')}</p><p class="muted">${E(x.type)} · ${new Date(x.at).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'})}</p><p style="white-space:pre-wrap">${E(x.body)}</p>${x.button?`<p><a class="parent-link-button" href="${E(x.button.url)}" target="_blank" rel="noopener noreferrer">${E(x.button.name)} ↗</a></p>`:''}<div class="row">${btn('내용 수정',`notification:${x.id}`)}${btn('복사',`copy-notification:${x.id}`)}${btn('검토 완료',`review-notification:${x.id}`,'quiet')}</div></div>`).join('')||'<div class="card empty">작성된 알림이 없습니다.<br>학생별 안내 문구를 만들어 보세요.</div>'}</div>`}
on('add-notification',()=>editNotification());function editNotification(id){staffOnly();const item=d.notifications.find(x=>x.id===id),s=visibleStudents()[0];if(!s)throw Error('담당 학생을 먼저 등록해 주세요.');if(item)scope(item.studentId);open(id?'알림 문구 수정':'학부모 알림 초안',`${select('학생','studentId',opts(visibleStudents(),x=>x.id,x=>x.name,item?.studentId||s.id))}${select('알림 유형','type',opts(['학습 안내','출결 안내','수강료 안내','상담 안내'],x=>x,x=>x,item?.type||'학습 안내'))}${area('안내 문구','body',item?.body||'안녕하세요, 더봄어학원입니다. 🌿\n오늘 학습 내용을 안내드립니다.\n\n꾸준히 성장할 수 있도록 함께 살피겠습니다. 감사합니다.')}<p class="muted">저장해도 학부모에게 전송되지 않습니다.</p>`,v=>{scope(v.get('studentId'));if(!v.get('body').trim())throw Error('안내 문구를 입력해 주세요.');return commit('학부모 알림 초안 저장',n=>{const x={id:id||M.uid(),studentId:v.get('studentId'),type:v.get('type'),body:v.get('body').trim(),status:'draft',at:new Date().toISOString()};if(id)Object.assign(n.notifications.find(z=>z.id===id),x);else n.notifications.push(x)})},'초안 저장')}
function reports(){staffOnly();const list=d.reports.filter(x=>visibleStudents().some(s=>s.id===x.studentId)),r=list.find(x=>x.id===reportId);return head('MONTHLY LEARNING REPORT','월간 학습 리포트','선택 월의 출결·완료 Unit과 현재 누적 진도를 함께 정리해요.',btn('+ 리포트 생성','create-report',''))+`<div class="tabs no-print">${list.map(x=>btn(E(x.name)+' · '+E(x.month),`show-report:${x.id}`,x.id===reportId?'active':'')).join('')}</div>${r?`<div class="row no-print" style="justify-content:flex-end;margin-bottom:16px">${badge(r.reviewedAt?'검토 확정':'코멘트 검토 필요',r.reviewedAt?'':'amber')}${btn('코멘트·AI 초안',`report-edit:${r.id}`)}${btn('코멘트 검토 확정',`report-confirm:${r.id}`)}${btn('학부모 알림 초안으로',`report-notify:${r.id}`)}${btn('인쇄 / PDF 저장','print-report','')}</div>${parentControls('report',r)}${reportHTML(r)}`:'<div class="card empty">학생과 월을 선택해 리포트를 생성해 보세요.<br>생성 시점의 내용을 저장하며 이후 학습 변경과 구분됩니다.</div>'}`}
function reportHTML(r){return `<article class="report"><header><div class="eyebrow">THE BOM · PLAY, LEARN, BLOOM</div><h1>월간 학습 리포트</h1><div class="row between"><span>${E(r.month)} · ${E(r.name)} (${E(r.grade)})</span>${badge('테스트 리포트')}</div></header><h2>이번 달 출결</h2><p>등원 ${r.attendance.present}회 &nbsp; · &nbsp; 지각 ${r.attendance.late}회 &nbsp; · &nbsp; 결석 ${r.attendance.absent}회</p><h2 style="margin-top:25px">교재별 학습 현황</h2>${r.learning.map(l=>`<div class="activity"><b>${E(l.title)}</b><div class="row between"><span class="muted">누적 ${l.done}/${l.total}단계 · ${l.percent}%</span><span class="muted">이번 달 확인 완료: ${l.monthCompleted.length?l.monthCompleted.map(u=>'Unit '+u).join(', '):'없음'}</span></div>${bar(l.percent)}</div>`).join('')||'<p class="muted">배정된 교재가 없습니다.</p>'}${r.daily?`<h2 style="margin-top:25px">숙제·단어시험</h2><p>숙제 O ${r.daily.homeworkO}회 · X ${r.daily.homeworkX}회</p><p>단어시험 ${r.daily.testCount}회 · 평균 ${r.daily.wordAverage===null?'기록 없음':r.daily.wordAverage+'점 (100점 환산)'}</p>`:''}<h2 style="margin-top:25px">선생님 코멘트</h2><div class="comment">${E(r.comment)}</div>${r.recordingUrl?`<h2 style="margin-top:25px">녹음 자료</h2><a href="${E(r.recordingUrl)}" target="_blank" rel="noopener noreferrer">${E(r.recordingTitle||'우리 아이 녹음 듣기')} ↗</a>`:''}${r.homework?.trim()?`<h2 style="margin-top:25px">가정에서 함께해 주세요</h2><p style="white-space:pre-wrap">${E(r.homework)}</p>`:''}<footer class="muted" style="margin-top:30px;border-top:1px solid var(--line);padding-top:15px">더봄어학원 · 생성 ${new Date(r.createdAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}<br>가상 데이터 기반 시연용 리포트 · 학습률은 생성 시점 누적 수치입니다.</footer></article>`}
on('create-report',()=>{staffOnly();open('월간 리포트 생성',`${select('학생','studentId',opts(visibleStudents(),x=>x.id,x=>x.name))}${f('기준 월','month',reportMonth,'month','required')}<p class="muted">동일 월의 리포트가 있어도 이전 내용을 보존하고 새 버전을 생성합니다.</p>`,v=>{scope(v.get('studentId'));const r=M.report(d,v.get('studentId'),v.get('month'));reportId=r.id;reportMonth=r.month;return commit('월간 리포트 생성',n=>n.reports.push(r))},'생성')});
on('print-report',()=>window.print());
function settings(){adminOnly();return backupSettingsHTML()+accountAccessHTML()+messagingPreparationHTML()+head('SANDBOX SETTINGS','테스트 설정',cloud?'운영 환경과 분리된 비공개 서버에 저장합니다.':'현재 브라우저의 가상 시연 저장소입니다.')+`<div class="columns"><div class="card"><h2>테스트 데이터 관리</h2><p>${cloud?'수정한 내용은 로그인한 계정의 비공개 테스트 서버에 저장됩니다. 같은 계정으로 다른 기기에서도 확인할 수 있어요.':'수정한 내용은 현재 기기의 이 브라우저에만 저장됩니다. 기기를 바꾸면 공유되지 않습니다.'}</p><p class="muted">모든 모듈은 가상 데이터로 동작합니다. 로그인, 서버 권한, 카카오 전송, 실제 결제 연결은 운영 전 추가 검증이 필요합니다.</p><div class="row">${btn('테스트 데이터 JSON 내보내기','export-json')}${btn('가상 데이터로 초기화','reset','danger')}</div></div><div class="card"><h2>확인해 볼 흐름</h2><p class="muted">① 교재·Unit → Unit 2의 쓰기 과정 확인<br>② 학생 화면 → 학습 단계 완료<br>③ 원장 화면 → 최종 확인<br>④ 태블릿 출결 → 1001 등원·하원<br>⑤ 수강료 → 부분 수납<br>⑥ 리포트 생성 → PDF 저장</p></div></div><div class="card"><h2>변경 기록</h2><div class="table-wrap"><table><thead><tr><th>시간</th><th>작업자 (시연)</th><th>내용</th></tr></thead><tbody>${d.audit.slice().reverse().map(x=>`<tr><td>${new Date(x.at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}</td><td>${E(x.actor)}</td><td>${E(x.action)}</td></tr>`).join('')}</tbody></table></div><p class="muted">브라우저에 보관되는 시연용 활동 기록입니다. 변조 방지 감사 로그는 아닙니다.</p></div>`}
function studentPage(){
 const all=d.students.filter(x=>x.active);if(!all.some(x=>x.id===studentId))studentId=all[0]?.id;const s=student(studentId);if(!s)return '<div class="card empty">선생님이 학습을 준비하고 있어요. 🌱</div>';
 if(M.isClassDay(d,s,M.today())===false&&!studentFreeReview)return `<div class="student-shell"><div class="student-welcome"><div><h1>오늘은 쉬어가는 날 🌼</h1><p>다음 수업에서 만나요! 원하면 복습할 수 있어요.</p></div></div><details class="demo-student"><summary>테스트할 학생 바꾸기</summary><select aria-label="시연할 학생" data-change="studentId">${opts(all,x=>x.id,x=>x.name,studentId)}</select></details><div class="card"><h2>📅 내 수업시간표</h2><p>${E(studentScheduleText(s))}</p>${btn('복습할 교재 보기','student-free-review','')}</div></div>`;
 const as=d.assignments.filter(x=>x.studentId===studentId&&!x.archived&&(studentFreeReview?M.studentUnits(d,x,true).length:M.assignmentOnDate(d,x)));const a=as.find(x=>x.id===selectedAssignment)||as[0];if(a)selectedAssignment=a.id;const b=a&&M.book(d,a.bookId),availableUnits=a?M.studentUnits(d,a,studentFreeReview):[];const selectionKey=studentId+'|'+(a?.id||'')+'|'+M.today()+'|'+studentFreeReview;if(studentViewKey!==selectionKey||!availableUnits.includes(unit)){unit=studentFreeReview?availableUnits[0]:a?M.nextUnit(d,a):1;studentViewKey=selectionKey}const p=a&&M.progress(d,a,unit),steps=a?M.effectiveSteps(d,a,unit):[],done=steps.filter(x=>p?.checked.includes(x.id)).length,first=steps.findIndex(x=>!p?.checked.includes(x.id)),mat=a?d.materials.find(x=>x.bookId===a.bookId&&x.unit===unit)||{}:{};
 return `<div class="student-shell"><div class="student-welcome"><div><span class="student-kicker">PLAY · LEARN · BLOOM</span><h1>안녕, ${E(s.name.replace('가상학생 ',''))}! <span>🌼</span></h1><p>작은 한 걸음이 모여, 오늘도 쑥쑥!</p></div><div class="sprout-friend" aria-hidden="true"><div class="leaf left"></div><div class="leaf right"></div><div class="sprout-face"><i></i><i></i><b>ᴗ</b></div></div></div><details class="demo-student"><summary>테스트할 학생 바꾸기</summary><label for="student-demo">시연할 학생</label><select id="student-demo" data-change="studentId">${opts(all,x=>x.id,x=>x.name,studentId)}</select></details>
 ${studentScoreCard(s)}<section class="card student-books"><h2><span class="section-number">1</span> ${studentFreeReview?'완료한 교재를 복습해요':'오늘 공부할 교재'} <span class="section-emoji">📚</span></h2><div class="book-picks">${as.map((x,i)=>{const selected=x.id===a.id,book=M.book(d,x.bookId);return `<button data-action="choose-assignment:${E(x.id)}" class="book-pick ${selected?'selected':''}" aria-pressed="${selected}"><span class="book-cover cover-${i%3}" aria-hidden="true">${['📗','📙','📘'][i%3]}</span><span><strong>${E(book.title)}</strong><small>${selected?'지금 공부하는 교재':'눌러서 이 교재 공부하기'}</small></span><span class="book-tick">${selected?'✓':'→'}</span></button>`}).join('')||'<div class="empty">오늘 이 요일에 배정된 교재가 없어요. 다음 수업에서 이어서 공부해요. 🌱</div>'}</div></section>
 ${!a?'':`<section class="card student-units"><div class="row between"><h2><span class="section-number">2</span> Unit을 골라요 <span class="section-emoji">🔎</span></h2><span class="muted">${M.progress(d,a,M.nextUnit(d,a))?.approvedAt?'모든 Unit 확인 완료':'현재 학습 Unit '+M.nextUnit(d,a)}</span></div><div class="unit-picks">${availableUnits.map(u=>{const approved=M.progress(d,a,u)?.approvedAt;return `<button data-action="student-unit" data-unit="${u}" class="unit-pick ${unit===u?'selected':''} ${approved?'approved':''}" aria-pressed="${unit===u}"><span>Unit ${u}</span><small>${approved?'🌟 확인 완료':unit===u?'지금 학습':'학습하기'}</small></button>`}).join('')}</div><p class="muted student-total">현재 Unit을 모두 마치고 선생님 확인을 받으면 다음 Unit이 열려요.<br>이 교재 전체 학습 ${M.stats(d,a).percent}% 완료 ${bar(M.stats(d,a).percent)}</p></section>
 <section class="card student-lesson"><div class="row between"><h2><span class="section-number">3</span> 하나씩 공부해요 <span class="section-emoji">✏️</span></h2><span class="lesson-pill">Unit ${unit} · ${done}/${steps.length} 완료</span></div><div class="lesson-progress"><div class="lesson-progress-top"><strong>${p?.approvedAt?'선생님 확인까지 끝났어요! 🌟':done===steps.length&&steps.length?'잘했어요! 오늘의 학습 완료 🎉':`지금까지 ${done}단계 완료!`}</strong><span>${steps.length?Math.round(done/steps.length*100):0}%</span></div>${bar(steps.length?Math.round(done/steps.length*100):0)}<div class="growth-dots" aria-hidden="true">${steps.map((_,i)=>`<span class="${p?.checked.includes(steps[i].id)?'grown':''}">${p?.checked.includes(steps[i].id)?'🌼':'·'}</span>`).join('')}</div></div>
 ${['word','reading'].filter(k=>!steps.some(st=>st.kind===k)&&(mat[k+'Data']||mat[k+'Url']||mat[k+'PageUrl'])).map(k=>`<div class="card"><h3>🎧 ${k==='word'?'단어':'리딩'} 음원 자료</h3>${mat[k+'Data']||mat[k+'Url']?audioPlayer(mat[k+'Data']||mat[k+'Url'],'Unit 음원'):''}${mat[k+'PageUrl']?`<a href="${E(mat[k+'PageUrl'])}" target="_blank" rel="noopener noreferrer">자료실 열기 ↗</a>`:''}</div>`).join('')}
 ${steps.map((st,i)=>{const checked=p?.checked.includes(st.id),audio=st.kind==='word'?(mat.wordData||mat.wordUrl):st.kind==='reading'?(mat.readingData||mat.readingUrl):null,icon=st.kind==='word'||st.kind==='reading'?'🎧':st.kind==='classcard'?'🎤':/마인드맵/.test(st.name)?'🌳':/쓰기|영작/.test(st.name)?'✍️':/Test|테스트/.test(st.name)?'🌟':'📖';return `<article class="student-step ${checked?'done':''} ${i===first?'next':''}"><label class="step-label"><input type="checkbox" data-toggle="${E(st.id)}" ${checked?'checked':''} ${!M.studentCanStudy(d,a,unit)||studentFreeReview?'disabled':''}><span class="step-number" aria-hidden="true">${checked?'✓':String(i+1).padStart(2,'0')}</span><span class="step-heading"><strong>${icon} ${E(st.name)}</strong><small>${E(st.page||'차근차근 따라 해요')}${i===first?' · 지금 할 학습':''}</small></span><span class="step-state">${checked?'완료!':'다 하면 체크'}</span></label><div class="step-body"><p>${E(st.desc)}</p>${['word','reading'].includes(st.kind)?audio?audioPlayer(audio,st.name+' 음원'):'<span class="audio-pending">🎧 선생님이 음원을 준비하고 있어요.</span>':''}${['word','reading'].includes(st.kind)&&mat[st.kind+'PageUrl']?`<p><a class="secondary" href="${E(mat[st.kind+'PageUrl'])}" target="_blank" rel="noopener noreferrer">📂 ${st.kind==='word'?'단어':'리딩'} 자료실 열기 ↗</a></p>`:''}${st.kind==='classcard'?`<a class="classcard-play" href="${E(mat.classcardUrl||'intent://#Intent;package=classcard.net;end')}" ${mat.classcardUrl?'target="_blank" rel="noopener noreferrer"':''}>🎤 클래스카드 열기 <span>→</span></a>`:''}</div></article>`}).join('')||'<div class="empty">선생님이 학습 순서를 준비하고 있어요. 🌱</div>'}
 <div class="student-finish">${p?.approvedAt?'🌟 선생님도 확인했어요. 정말 잘했어요!':steps.length&&done===steps.length?'🎉 모두 마쳤어요! 선생님께 확인받아요.':'🌱 공부를 마치면 네모에 체크! 하나씩 하면 돼요.'}</div></section>`}<footer class="student-footer">오늘도 한 뼘 자란 너를 응원해 💚<br><small>THE BOM ENGLISH ACADEMY</small></footer></div>`;
}
on('student-unit',el=>{const a=d.assignments.find(x=>x.id===selectedAssignment),selected=Number(el.dataset.unit);if(!a||!M.studentUnits(d,a,studentFreeReview).includes(selected))throw Error('현재 Unit을 마치고 선생님께 확인받으면 다음 Unit이 열려요.');unit=selected;render()});

function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const csv=rows=>'\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\r\n');
on('attendance-csv',()=>{staffOnly();download('thebom-test-attendance-'+attDate+'.csv',csv([['날짜','학생','상태','등원','하원'],...d.attendance.filter(x=>x.date===attDate&&visibleStudents().some(s=>s.id===x.studentId)).map(x=>[x.date,student(x.studentId)?.name,x.status,time(x.in),time(x.out)])]),'text/csv;charset=utf-8')});
on('tuition-csv',()=>{adminOnly();download('thebom-test-billing-'+invoiceMonth+'.csv',csv([['월','학생','청구액','수납액','미수금','상태'],...d.invoices.filter(x=>x.month===invoiceMonth).map(x=>[x.month,student(x.studentId)?.name,x.amount,M.paid(x),x.cancelled?0:x.amount-M.paid(x),x.cancelled?'취소':'유효'])]),'text/csv;charset=utf-8')});
on('export-json',()=>{adminOnly();download('thebom-sandbox-'+M.today()+'.json',JSON.stringify(d,null,2),'application/json')});
on('reset',()=>{adminOnly();open('가상 데이터로 초기화 · 주의',`<p class="note">등록한 실제 교재와 학원 기록도 가상 데이터로 교체됩니다. 대량 자료를 등록했다면 초기화하지 마세요. 온라인에서는 초기화 직전 현재 상태를 자동 백업합니다. 업로드한 음원 파일 자체는 지우지 않습니다.</p>${f('진행하려면 초기화라고 입력해 주세요','confirm','','text','required')}`,async v=>{if(v.get('confirm')!=='초기화')throw Error('초기화라고 입력해 주세요.');await commit('직접 확인한 테스트 초기화',n=>{const revision=n.revision;Object.assign(n,M.seed());n.revision=revision});dailyDrafts.clear();dailyQueue.clear();storageProblem=false;reportId=null;render()},'확인 후 초기화')});

async function dispatch(action,el){if(actions[action])return actions[action](el);const [type,id,arg]=action.split(':');switch(type){case 'legacy-category-remove':return removeLegacyCategory(id);case 'category-remove':return removeCategoryDialog(id);case 'category-recover':adminOnly();return commit('카테고리 복원',n=>M.recoverCategory(n,id));case 'unassign':return unassignDialog(id);case 'assignment-restore':adminOnly();return commit('교재 배정 복원',n=>M.setAssignmentArchived(n,id,false));case 'book-trash':return confirmBookTrash(id);case 'book-restore':adminOnly();return commit('휴지통 교재 복원',n=>M.restoreBook(n,id));case 'notice-invoice':return actions['notice-invoice'](id);case 'student-status':return changeStudentStatus(id);case 'student-history':return studentHistory(id);case 'student-edit':return editStudent(id);case 'assign':return assign(id);case 'detail':return detail(id);case 'individual':modal.close();return individualEditor(id);case 'archive-assignment':adminOnly();if(confirm('배정을 보관하고 학생 화면에서 숨길까요? 기존 기록은 유지됩니다.')){await commit('교재 배정 보관',n=>n.assignments.find(x=>x.id===id).archived=true);modal.close()}return;case 'approve':{const a=d.assignments.find(x=>x.id===id);scope(a.studentId);await commit('Unit '+arg+' 선생님 확인',n=>M.approve(n,id,Number(arg),role==='admin'?'admin-demo':teacherId));if(modal.open){modal.close();detail(id)}return}case 'book-edit':return editBook(id);case 'book-steps':uploaded={};return stepsEditor(id);case 'step-up':case 'step-down':case 'step-delete':staffOnly();collectSteps();{const i=Number(id),j=i+(type==='step-up'?-1:1);if(type==='step-delete')draftSteps.splice(i,1);else if(j>=0&&j<draftSteps.length)[draftSteps[i],draftSteps[j]]=[draftSteps[j],draftSteps[i]];dirty=true;drawSteps()}return;case 'attend':scope(id);return commit('출결 '+(arg==='in'?'등원':'하원'),n=>M.attend(n,id,attDate,arg));case 'attendance-edit':return attendanceEdit(id);case 'key':{const input=$('#kiosk-pin');if(id==='지우기')input.value='';else if(id==='←')input.value=input.value.slice(0,-1);else if(input.value.length<4)input.value+=id;return}case 'teacher-status':return changeTeacherStatus(id);case 'teacher-edit':return editTeacher(id);case 'invoice':return invoiceDetail(id);case 'cancel-invoice':adminOnly();if(confirm('청구를 취소하고 기록은 보관할까요?')){await commit('수강료 청구 취소',n=>{const i=n.invoices.find(x=>x.id===id);if(M.paid(i))throw Error('수납 기록이 있는 청구는 취소할 수 없습니다.');i.cancelled=true});modal.close()}return;case 'notification':return editNotification(id);case 'copy-notification':{const x=d.notifications.find(x=>x.id===id);scope(x.studentId);await navigator.clipboard.writeText(x.body);toast('안내 문구를 복사했습니다. 직접 확인한 뒤 보내 주세요.');return}case 'review-notification':{const x=d.notifications.find(x=>x.id===id);scope(x.studentId);return commit('학부모 알림 검토',n=>n.notifications.find(x=>x.id===id).status='reviewed')}case 'show-report':reportId=id;render();return;case 'report-edit':return reportCommentEditor(id);case 'report-confirm':{const r=d.reports.find(x=>x.id===id);scope(r.studentId);return commit('리포트 코멘트 검토 확정',n=>{const r=n.reports.find(x=>x.id===id);r.reviewedAt=new Date().toISOString();r.status='reviewed'})}case 'attendance-notice':{scope(id);await commit('출결 안내 초안 준비',n=>M.prepareAttendanceNotice(n,id,attDate,arg));view='notifications';render();return}case 'backup-restore':return previewBackupRestore(Number(id));case 'parent-create':return manageParentLink(id,arg,'create');case 'parent-revoke':return manageParentLink(id,arg,'revoke');case 'announcement-edit':return announcementEditor(id);case 'announcement-draft':return announcementRecipients(id,arg);case 'report-notify':{const r=d.reports.find(x=>x.id===id);scope(r.studentId);if(!r.reviewedAt)throw Error('코멘트를 확인하고 검토 확정을 먼저 눌러 주세요.');const link=parentLinkCache.get('report:'+id);if(!link)throw Error('‘확인 링크 생성’을 먼저 눌러 주세요. 현재는 비공개 테스트 링크입니다.');await commit('월간 리포트 링크 알림 초안',n=>n.notifications.push({id:M.uid(),studentId:r.studentId,type:'월간 리포트',body:`[더봄어학원]\n${r.name} 학생의 ${r.month} 학습 리포트가 준비되었습니다.\n아래 버튼을 눌러 확인해 주세요.`,button:{name:'리포트 확인하기',url:link.url},status:'draft',deliveryStatus:'integration_pending',at:new Date().toISOString()}));view='notifications';render();return}case 'choose-assignment':selectedAssignment=id;unit=M.nextUnit(d,d.assignments.find(x=>x.id===id));render();return;default:throw Error('지원하지 않는 동작입니다.')}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();Promise.resolve().then(()=>dispatch(el.dataset.action,el)).catch(err=>toast(err.message))});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.change){switch(el.dataset.change){case 'role':if(actualAccess&&actualAccess.role!=='admin')throw Error('로그인 계정의 권한은 화면에서 변경할 수 없습니다.');role=el.value;view=role==='student'?'student':'dashboard';break;case 'teacher':teacherId=el.value;break;case 'studentId':studentId=el.value;studentFreeReview=false;unit=1;break;case 'unit':unit=Number(el.value);break;case 'attDate':if(el.value)attDate=el.value;break;case 'invoiceMonth':if(el.value)invoiceMonth=el.value;break;}render()}if(el.dataset.toggle){if(role!=='student')throw Error('학생 화면에서만 학습 체크가 가능합니다.');const a=d.assignments.find(x=>x.id===selectedAssignment);if(a.studentId!==studentId)throw Error('학생 배정을 확인해 주세요.');if(studentFreeReview||!M.studentCanStudy(d,a,unit))throw Error('오늘의 교재와 현재 Unit만 학습할 수 있어요. 선생님 확인 후 다음 Unit이 열립니다.');return await commit('학습 단계 체크',n=>M.toggle(n,selectedAssignment,unit,el.dataset.toggle,el.checked))}if(el.dataset.audio){const file=el.files[0];if(!file)return;const limit=cloud?20*1024*1024:1500000;if(!(file.type.startsWith('audio/')||/\.(mp3|wav|m4a|ogg|aac|webm)$/i.test(file.name))||file.size>limit)throw Error((cloud?'20MB':'1.5MB')+' 이내의 음원 파일을 선택해 주세요.');audioUploadBusy++;let val;try{if(cloud){$('#upload-status').textContent='음원 전용 저장소에 업로드 중…';const response=await fetch('/api/audio',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file});const result=await response.json();if(!response.ok)throw Error(({test_storage_limit:'테스트 음원 저장 한도(100MB)에 도달했습니다.',unsupported_audio:'지원하는 MP3·WAV·M4A·OGG·WebM 파일을 선택해 주세요.',storage_not_configured:'음원 저장소 연결을 확인해 주세요.',file_too_large:'파일당 20MB 이내로 업로드해 주세요.'})[result.error]||'음원 업로드를 완료하지 못했습니다.');val=result.url;}else val=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>{const mime=file.type.startsWith('audio/')?file.type:({mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',ogg:'audio/ogg',aac:'audio/aac',webm:'audio/webm'}[file.name.split('.').pop().toLowerCase()]);res(String(r.result).replace(/^data:[^;]*;/,'data:'+mime+';'))};r.onerror=rej;r.readAsDataURL(file)});}finally{audioUploadBusy--}if(!el.isConnected)throw Error('교재 또는 Unit이 바뀌었습니다. 해당 Unit에서 음원을 다시 선택해 주세요.');const kind=el.dataset.audio==='wordUrl'?'word':'reading';if(cloud){uploaded[kind+'Url']=val;uploaded[kind+'Data']=null;$('[name="'+kind+'Url"]').value=val;}else uploaded[kind+'Data']=val;$('#preview-'+kind).innerHTML=audioPlayer(val,'업로드 음원 미리듣기');$('#upload-status').textContent=file.name+' · 저장 버튼을 누르면 Unit에 반영됩니다.';dirty=true}}catch(err){toast(err.message);if(el.dataset.toggle)render();if(el.type==='file')el.value=''}});
document.addEventListener('input',e=>{if(e.target.dataset.input==='student-search'){studentQuery=e.target.value;const pos=e.target.selectionStart;render();const input=$('[data-input="student-search"]');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='kiosk-pin')e.target.value=e.target.value.replace(/\D/g,'').slice(0,4)});
window.addEventListener('storage',e=>{if(e.key===M.KEY&&!cloud){if(modal.open){toast('다른 탭에서 데이터가 바뀌었습니다. 이 창을 새로고침한 뒤 다시 편집해 주세요.');return}try{d=e.newValue?JSON.parse(e.newValue):M.seed();dailyInvalidateSaved();render()}catch{toast('저장 데이터를 확인할 수 없습니다.')}}});
window.addEventListener('beforeunload',e=>{if((modal.open&&dirty)||dailyHasUnsaved()){e.preventDefault();e.returnValue=''}});
async function boot(){
 if(cloud){root.innerHTML='<div class="card" style="margin:40px">비공개 테스트 데이터를 불러오고 있습니다…</div>';try{const accessResponse=await fetch('/api/access',{cache:'no-store'});if(!accessResponse.ok)throw Error('등록되지 않았거나 중지된 계정입니다. 원장님에게 계정 연결을 요청해 주세요.');actualAccess=await accessResponse.json();localStorage.removeItem(M.KEY);if(actualAccess.role==='teacher'){role='teacher';teacherId=actualAccess.entityId;view='daily';}if(actualAccess.role==='student'){role='student';studentId=actualAccess.entityId;view='student';}const r=await fetch('/api/sandbox',{cache:'no-store'});if(!r.ok)throw Error('테스트 서버에 연결할 수 없습니다. 상단 주소를 새로고침해 주세요.');const remote=await r.json();d=remote.state??M.seed();storageProblem=false;}catch(e){root.innerHTML='<div class="card" style="margin:40px"><h2>테스트 데이터 연결 확인</h2><p>'+E(e.message)+'</p><a href="/" target="_top">테스트 사이트 다시 열기</a></div>';return}}
 if(!cloud){const candidate=M.clone(d),created=M.generateDueInvoices(candidate,M.today());if(created){candidate.revision=d.revision+1;try{localStorage.setItem(demoKey,JSON.stringify(candidate));d=candidate}catch{toast('자동 청구를 저장하지 못했습니다.')}}}
 render();
}
let labTab=initialView==='books'?'books':'overview',labBookId='',labUnit=1,labStudentId='',labAssignmentId='';
const labTabs=[['daily','오늘 빠른 입력'],['overview','학습 현황'],['books','교재 관리'],['categories','카테고리 관리'],['assign','학생·배정'],['plans','개별 진도표'],['weekly','요일별 학습 계획'],['materials','Unit 자료']];
function labView(){const selected=labTabs.some(x=>x[0]===labTab)?labTab:'overview';return `<section class="classic-lab"><div class="lab-intro"><span class="badge">🌿 THE BOM LEARNING LAB</span><h1>원장님 학습관리</h1><p>교재를 등록하고, 학생별 진도표와 학습 현황을 관리하세요.</p></div><nav class="lab-tabs" aria-label="리딩랩 관리 메뉴">${labTabs.map(([id,name])=>`<button data-action="lab-tab" data-id="${id}" class="${selected===id?'active':''}">${name}</button>`).join('')}</nav>${labPanel(selected)}</section>`}
function labSelectors(){if(!d.books.some(x=>x.id===labBookId&&!x.deletedAt))labBookId=d.books.find(x=>!x.deletedAt)?.id||'';if(!visibleStudents().some(x=>x.id===labStudentId))labStudentId=visibleStudents()[0]?.id||'';if(!visibleAssignments().some(x=>x.id===labAssignmentId))labAssignmentId=visibleAssignments()[0]?.id||'';const b=M.book(d,labBookId);if(labUnit>(b?.units||1))labUnit=1;return b}
function labPanel(tab){if(tab==='daily')return dailyView(true);const b=labSelectors(),students=visibleStudents(),as=visibleAssignments();
 if(tab==='overview')return `<div class="grid"><div class="card"><h2>👩‍🎓 학생</h2><strong class="lab-count">${students.filter(x=>x.active).length}명</strong></div><div class="card"><h2>📚 등록 교재</h2><strong class="lab-count">${d.books.filter(x=>!x.archived).length}권</strong></div><div class="card"><h2>📋 교재 배정</h2><strong class="lab-count">${as.length}건</strong></div></div><div class="card"><h2>학생별 학습 현황</h2>${learningTable(as)}</div>`;
 if(tab==='books')return `<div class="card"><h2>📚 새 교재 등록</h2><div class="lab-form" id="lab-book-form"><div class="formgrid">${f('교재명','labTitle','','text','placeholder="예: Easy Link 5" maxlength="100"')}${f('카테고리','labCategory','','text','placeholder="예: 리딩 / 초급" maxlength="50" list="lab-category-options"')}<datalist id="lab-category-options">${[...new Set([...(d.categories||[]).filter(c=>!c.deletedAt).map(c=>{const parent=(d.categories||[]).find(x=>x.id===c.parentId);return parent?parent.name+' / '+c.name:c.name})])].map(name=>`<option value="${E(name)}"></option>`).join('')}</datalist>${f('Unit 개수','labUnits',12,'number','min="1" max="200"')}</div>${btn('+ 교재 등록','lab-add-book','',role==='admin'?'':'disabled')}</div></div><div class="card"><div class="row between"><h2>교재 라이브러리</h2><span class="muted">교재 정보와 학습 과정을 바로 수정하세요.</span></div>${d.books.filter(book=>!book.deletedAt).map(book=>`<div class="lab-item"><div><b>📗 ${E(book.title)}</b><p class="muted">${E(book.category)} · ${book.units} Units · 기본 ${book.steps.length}단계 ${book.archived?'· 보관 중':''}</p></div><div class="row">${role==='admin'?btn('교재 정보 수정',`book-edit:${book.id}`):''}${btn('기본 단계 편집',`book-steps:${book.id}`)}<button class="secondary" data-action="lab-unit-editor" data-book="${E(book.id)}">Unit별 단계 편집</button><button class="secondary" data-action="lab-material-book" data-book="${E(book.id)}">음원·자료 연결</button>${role==='admin'?btn('삭제',`book-trash:${book.id}`,'danger'):''}</div></div>`).join('')||'<div class="empty">교재를 먼저 등록해 주세요.</div>'}${role==='admin'?bookTrashHTML():''}</div>`;
 if(tab==='categories'){const all=(d.categories||[]).filter(c=>!c.deletedAt);return `<div class="card"><h2>📁 카테고리 관리</h2><p class="muted">교재의 분류를 선택하기 쉽게 대분류와 하위 분류를 정리해요.</p><div class="formgrid">${f('새 대분류 이름','labRoot','','text','maxlength="40"')}</div>${btn('대분류 추가','lab-add-category','',role==='admin'?'':'disabled')}</div>${all.filter(x=>!x.parentId).map(c=>`<div class="card"><div class="row between"><h2>📁 ${E(c.name)}</h2><button class="secondary" data-action="lab-rename-category" data-id="${E(c.id)}">이름 수정</button>${role==='admin'?btn('삭제',`category-remove:${c.id}`,'danger'):''}</div>${all.filter(x=>x.parentId===c.id).map(ch=>`<div class="lab-item"><span>↳ ${E(ch.name)}</span><button class="secondary" data-action="lab-rename-category" data-id="${E(ch.id)}">이름 수정</button>${role==='admin'?btn('삭제',`category-remove:${ch.id}`,'danger'):''}</div>`).join('')}<div class="row"><input class="search" aria-label="${E(c.name)} 하위 카테고리" id="cat-${E(c.id)}" placeholder="새 하위 카테고리"><button data-action="lab-add-child" data-id="${E(c.id)}">하위 카테고리 추가</button></div></div>`).join('')}${legacyCategoriesHTML()}${categoryTrashHTML()}`}
 if(tab==='assign')return `<div class="card"><div class="row between"><h2>👩‍🎓 학생 등록</h2>${btn('+ 학생 등록','add-student','',role==='admin'?'':'disabled')}</div><p class="muted">학생 정보는 학생 관리 메뉴에서도 언제든 수정할 수 있어요.</p><div class="row">${students.map(s=>`<span class="badge">${E(s.name)} · ${E(s.grade)}</span>`).join('')}</div></div><div class="card"><h2>학생에게 교재 배정</h2><div class="formgrid">${select('학생','labAsStudent',opts(students.filter(x=>x.active),x=>x.id,x=>x.name,labStudentId))}${select('교재','labAsBook',opts(d.books.filter(x=>!x.archived),x=>x.id,x=>x.title,labBookId))}${f('시작 Unit','labAsStart',1,'number','min="1" max="200"')}</div>${btn('+ 교재 배정','lab-assign','',role==='admin'?'':'disabled')}</div><div class="card"><div class="row between"><h2>학생별 교재 배정</h2><input class="search" data-assignment-search aria-label="배정 학생·교재 검색" placeholder="학생 이름 또는 교재 검색"></div><p class="muted">학생 ${new Set(as.map(a=>a.studentId)).size}명 · 교재 배정 ${as.length}건 · 학생 이름을 누르면 접거나 펼칠 수 있어요.</p>${groupedAssignmentsHTML(as)}<p class="empty" data-assignment-empty hidden>검색 결과가 없습니다.</p>${assignmentArchiveHTML()}</div>`;
 if(tab==='plans'){const a=as.find(x=>x.id===labAssignmentId);return `<div class="card"><h2>학생별 맞춤 학습진도표</h2>${labAssignmentSelect(as)}${a?`<p class="muted">${a.customSteps?'이 학생의 개별 과정':'교재 기본 과정'} · Unit별 설정이 있는 경우 해당 과정이 우선 적용됩니다.</p>${(a.customSteps??M.book(d,a.bookId).steps).map((s,i)=>`<div class="lab-item"><div><b>${i+1}. ${E(s.name)}</b><p class="muted">${E(s.desc)} · ${E(s.page)}</p></div></div>`).join('')}${btn('이 학생의 학습 과정 편집',`individual:${a.id}`,'')}`:'<div class="empty">먼저 학생에게 교재를 배정해 주세요.</div>'}</div>`}
 if(tab==='weekly')return `<div class="card"><h2>📅 학생별 요일 학습 계획</h2><p class="muted">한 요일에 여러 교재를 배정할 수 있어요. 요일을 바꿔도 기존 진도는 유지됩니다.</p><div class="field"><label for="lab-student">학생</label><select id="lab-student" data-lab-change="student">${opts(students,x=>x.id,x=>x.name,labStudentId)}</select></div>${as.filter(a=>a.studentId===labStudentId).map(a=>`<div class="lab-item lab-week"><b>${E(M.book(d,a.bookId).title)}</b><div class="week">${['일','월','화','수','목','금','토'].map((day,i)=>`<label><input type="checkbox" data-week-assignment="${E(a.id)}" data-day="${i}" ${a.days.includes(i)?'checked':''}>${day}</label>`).join('')}</div></div>`).join('')||'<div class="empty">이 학생에게 배정된 교재가 없어요.</div>'}</div>`;
 if(tab==='materials')return `<div class="card"><h2>🎧 Unit별 학습 자료 연결</h2><p class="muted">교재와 Unit을 선택한 뒤 음원을 연결하세요.</p><div class="formgrid"><div class="field"><label for="lab-book">교재</label><select id="lab-book" data-lab-change="book">${opts(d.books.filter(x=>!x.deletedAt),x=>x.id,x=>x.title,labBookId)}</select></div><div class="field"><label for="lab-unit">Unit</label><select id="lab-unit" data-lab-change="unit">${Array.from({length:b?.units||0},(_,i)=>`<option value="${i+1}" ${labUnit===i+1?'selected':''}>Unit ${i+1}</option>`).join('')}</select></div></div>${b?`<form id="lab-material-form">${materialFields(b.id,labUnit)}${btn('자료 저장','lab-save-materials','',role==='admin'?'':'disabled')}</form>`:'<div class="empty">교재를 먼저 등록해 주세요.</div>'}</div>`;
 return '';
}
function labAssignmentSelect(as){return `<div class="field"><label for="lab-assignment">학생 · 교재</label><select id="lab-assignment" data-lab-change="assignment">${opts(as,x=>x.id,x=>student(x.studentId)?.name+' · '+M.book(d,x.bookId)?.title,labAssignmentId)}</select></div>`}
on('lab-tab',el=>{labTab=el.dataset.id;uploaded={};render()});
on('lab-add-book',()=>{adminOnly();const title=$('[name="labTitle"]').value.trim(),category=$('[name="labCategory"]').value.trim()||'기타',units=Number($('[name="labUnits"]').value);if(!title||!Number.isInteger(units)||units<1||units>200)throw Error('교재명과 Unit 개수를 확인해 주세요.');return commit('교재 등록',n=>n.books.push({id:M.uid(),title,category,units,steps:[],archived:false}))});
on('lab-unit-editor',el=>{stepsEditor(el.dataset.book,1)});
on('lab-material-book',el=>{labBookId=el.dataset.book;labUnit=1;labTab='materials';uploaded={};render()});
on('lab-save-materials',()=>{adminOnly();const form=$('#lab-material-form');if(!form.reportValidity())return;return commit('Unit 학습 자료 저장',n=>saveMaterial(n,labBookId,labUnit,new FormData(form)))});
on('lab-assign',()=>{adminOnly();const studentId=$('[name="labAsStudent"]').value,bookId=$('[name="labAsBook"]').value,start=Number($('[name="labAsStart"]').value),b=M.book(d,bookId);if(!studentId||!b||!Number.isInteger(start)||start<1||start>b.units)throw Error('학생·교재·시작 Unit을 확인해 주세요.');if(d.assignments.some(a=>a.studentId===studentId&&a.bookId===bookId&&!a.archived))throw Error('이미 배정된 교재입니다.');return commit('학생 교재 배정',n=>n.assignments.push({id:M.uid(),studentId,bookId,start,days:[],customSteps:null,archived:false}))});
function newCategory(name,parentId=null){adminOnly();if(!name.trim())throw Error('카테고리 이름을 입력해 주세요.');if((d.categories||[]).some(c=>!c.deletedAt&&c.name===name.trim()&&(c.parentId||null)===parentId))throw Error('같은 카테고리가 이미 있어요.');return commit('카테고리 추가',n=>{n.categories??=[];n.categories.push({id:M.uid(),name:name.trim(),parentId})})}
on('lab-add-category',()=>newCategory($('[name="labRoot"]').value));
on('lab-add-child',el=>newCategory(document.getElementById('cat-'+el.dataset.id).value,el.dataset.id));
on('lab-rename-category',el=>{adminOnly();const c=(d.categories||[]).find(x=>x.id===el.dataset.id);open('카테고리 이름 수정',f('이름','name',c.name,'text','required maxlength="40"'),v=>{const name=v.get('name').trim();if(!name)throw Error('이름을 입력해 주세요.');return commit('카테고리 이름 수정',n=>n.categories.find(x=>x.id===c.id).name=name)})});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.dataset.labChange){uploaded={};switch(el.dataset.labChange){case 'book':labBookId=el.value;labUnit=1;break;case 'unit':labUnit=Number(el.value);break;case 'student':labStudentId=el.value;break;case 'assignment':labAssignmentId=el.value;break;}render()}if(el.dataset.weekAssignment){const id=el.dataset.weekAssignment,a=d.assignments.find(x=>x.id===id),day=Number(el.dataset.day),checked=el.checked;scope(a.studentId);await commit('요일별 학습 계획 수정',n=>{const row=n.assignments.find(x=>x.id===id);row.days=checked?[...new Set([...row.days,day])].sort():row.days.filter(x=>x!==day)})}}catch(err){toast(err.message);render()}});

let dailyShowAll=false;
let dailyDate=M.today(),dailyGrade='전체',dailyQuery='',dailyOnlyMissing=false;
const dailyDrafts=new Map(),dailyQueue=new Map();let dailyWorking=false,dailyTimer=null;
const dailyKey=(id,date)=>date+'|'+id;
function dailyBase(id,date){const row=M.dailyRecord(d,id,date);return {wordHomework:null,personalHomework:null,wordHomeworkTask:'',personalHomeworkTask:'',...(row?M.clone(row):{studentId:id,date,units:M.dailyPlan(d,id,date),homework:null,wordScore:null,wordMax:100,note:''})}}
function dailyEntry(id,date=dailyDate){const key=dailyKey(id,date);if(!dailyDrafts.has(key))dailyDrafts.set(key,{data:dailyBase(id,date),seq:0,status:M.dailyRecord(d,id,date)?'saved':'blank',error:''});return dailyDrafts.get(key)}
function dailyInvalidateSaved(){for(const [key,entry] of dailyDrafts){if(['saved','blank'].includes(entry.status))dailyDrafts.delete(key)}}
function dailyHasUnsaved(){return [...dailyDrafts.values()].some(x=>['dirty','saving','error'].includes(x.status))}
function dailyMissing(data){return data.wordHomework===null||data.personalHomework===null||data.wordScore===null||data.wordScore===''||!data.units.length}
function dailyView(inside=false){staffOnly();if(!dailyStudents().some(s=>s.grade===dailyGrade))dailyGrade='전체';const sts=dailyStudents(),grades=['전체',...new Set(sts.map(s=>s.grade))],shown=sts.filter(s=>dailyGrade==='전체'||s.grade===dailyGrade);
 return `<section class="daily-workspace">${inside?'<h2>☑ 오늘 빠른 입력</h2>':head('QUICK CLASS RECORD','오늘 빠른 입력','학생별 Unit·숙제·단어시험을 한 줄에서 입력해요.',btn('CSV 내려받기','daily-csv'))}<div class="daily-grade-tabs" aria-label="학년 선택">${grades.map(g=>`<button class="${dailyGrade===g?'active':''}" data-action="daily-grade" data-grade="${E(g)}">${E(g)}</button>`).join('')}</div><div class="daily-toolbar"><div class="row"><button class="secondary" data-action="daily-prev" aria-label="전날">‹</button><input type="date" aria-label="기록 날짜" data-daily-date value="${dailyDate}"><button class="secondary" data-action="daily-next" aria-label="다음 날">›</button>${btn('오늘','daily-today','secondary')}${btn('최신 기록 불러오기','daily-reload','secondary')}<span class="daily-date-label">${new Date(dailyDate+'T12:00:00+09:00').toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul',weekday:'long'})}</span></div><div class="row"><input class="search" aria-label="빠른 입력 학생 검색" data-daily-search placeholder="학생 이름 검색" value="${E(dailyQuery)}"><label class="daily-filter"><input type="checkbox" data-daily-show-all ${dailyShowAll?'checked':''}>수업 없는 학생도 보기</label><label class="daily-filter"><input type="checkbox" data-daily-missing ${dailyOnlyMissing?'checked':''}>미입력만</label><button class="secondary" data-action="daily-save-all">지금 저장</button></div></div><div class="daily-hint"><span>💡 지난 숙제 내용을 확인하고 수행 여부를 입력하세요. 오늘 내준 숙제는 다음 수업의 선생님께 공유됩니다. 숙제는 <b>O / X</b>, 단어시험은 <b>점수</b>만 입력하세요. 변경한 칸은 자동 저장됩니다.</span><span>점수 입력 후 <kbd>Enter</kbd> → 다음 학생</span></div><div class="daily-summary" id="daily-summary"></div><div class="daily-table-wrap"><table class="daily-table"><thead><tr><th class="daily-student-col">학생</th><th>오늘 공부하는 교재 · Unit</th><th class="daily-homework-col">단어숙제</th><th class="daily-homework-col">개인숙제</th><th class="daily-score-col">단어시험 점수</th><th>한 줄 메모</th><th class="daily-status-col">저장</th></tr></thead><tbody>${shown.map(s=>dailyRow(s)).join('')}</tbody></table>${!shown.length?'<div class="empty">이 학년에 해당하는 학생이 없습니다.</div>':''}<div class="empty" id="daily-filter-empty" hidden>검색 조건에 맞는 학생이 없습니다.</div></div><p class="muted daily-bottom">숙제 미입력과 X, 시험 미응시와 0점은 따로 보관합니다. Unit 기록은 그날 수업 기록이며 학습 완료 체크를 자동으로 바꾸지 않습니다.</p></section>`;
}
function dailyRow(s){const entry=dailyEntry(s.id),r=entry.data;return `<tr data-daily-row="${E(s.id)}" data-date="${dailyDate}" data-name="${E(s.name)}"><td class="daily-student-col"><strong>${E(s.name)}</strong><small>${E(s.grade)} · ${E(teacher(s.teacherId)?.name||'담당 미지정')}</small><small>${M.isClassDay(d,s,dailyDate)===null?'시간표 미설정':M.isClassDay(d,s,dailyDate)===false?'수업 없음':M.classTimes(s,dailyDate).map(x=>x.start+'~'+x.end).join(' · ')}</small></td><td><div class="daily-units" data-unit-controls>${dailyUnitControls(s.id,dailyDate,r)}</div></td>${homeworkCell(s,r,'wordHomework','단어숙제')}${homeworkCell(s,r,'personalHomework','개인숙제')}<td class="daily-score-col"><div class="daily-score-inputs"><input type="number" min="0" max="${r.wordMax}" step="1" inputmode="numeric" data-daily-field="wordScore" value="${E(r.wordScore??'')}" placeholder="점수" aria-label="${E(s.name)} 단어시험 점수"><span>/</span><input type="number" min="1" max="1000" step="1" inputmode="numeric" data-daily-field="wordMax" value="${E(r.wordMax)}" aria-label="${E(s.name)} 단어시험 만점"></div><small>빈칸 = 미응시 · 0점 입력 가능</small></td><td><input class="daily-note" maxlength="1000" data-daily-field="note" value="${E(r.note)}" placeholder="예: 숙제 재확인 / 단어 재시험" aria-label="${E(s.name)} 수업 메모"></td><td class="daily-status-col"><span data-daily-status class="save-${entry.status}" role="status">${dailyStatus(entry)}</span><button class="daily-row-save" data-action="daily-row-save">${entry.status==='error'?'다시 저장':'저장'}</button></td></tr>`}
function dailyUnitControls(id,date,r){const as=d.assignments.filter(a=>a.studentId===id&&!a.archived);return r.units.map(u=>{const a=d.assignments.find(x=>x.id===u.assignmentId),b=a&&M.book(d,a.bookId);if(!a||!b)return '';return `<div class="daily-unit-line"><span title="${E(b.title)}">📗 ${E(b.title)}</span><select data-daily-unit="${E(a.id)}" aria-label="${E(student(id)?.name)} ${E(b.title)} 오늘 Unit">${Array.from({length:b.units-a.start+1},(_,i)=>i+a.start).map(n=>`<option value="${n}" ${n===u.unit?'selected':''}>Unit ${n}</option>`).join('')}</select><button class="daily-remove" data-action="daily-remove-unit" data-assignment="${E(a.id)}" aria-label="${E(b.title)} 오늘 학습에서 제외">×</button></div>`}).join('')+`<select class="daily-add-book" data-daily-add-book aria-label="${E(student(id)?.name)} 오늘 학습 교재 추가"><option value="">${r.units.length?'+ 교재 추가':as.length?'오늘 공부할 교재 선택':'배정된 교재 없음'}</option>${as.filter(a=>!r.units.some(u=>u.assignmentId===a.id)).map(a=>`<option value="${E(a.id)}">${E(M.book(d,a.bookId)?.title)}</option>`).join('')}</select>`}
function dailyStatus(entry){return entry.status==='saved'?'✓ 저장됨':entry.status==='saving'?'저장 중…':entry.status==='dirty'?'입력 중…':entry.status==='error'?'저장 실패':'미입력'}
function dailyRowNode(id,date){return [...document.querySelectorAll('[data-daily-row]')].find(el=>el.dataset.dailyRow===id&&el.dataset.date===date)}
function dailyPaint(id,date,units=false){const row=dailyRowNode(id,date),entry=dailyEntry(id,date);if(!row)return;const status=row.querySelector('[data-daily-status]');status.textContent=dailyStatus(entry);status.className='save-'+entry.status;status.title=entry.error||'';row.querySelector('.daily-row-save').textContent=entry.status==='error'?'다시 저장':'저장';row.querySelectorAll('[data-action="daily-homework"]').forEach(b=>{const chosen=entry.data[b.dataset.field||'homework']===(b.dataset.value||null);b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen))});if(units)row.querySelector('[data-unit-controls]').innerHTML=dailyUnitControls(id,date,entry.data);const score=row.querySelector('[data-daily-field="wordScore"]');score.max=entry.data.wordMax;dailyRefreshSummary();dailyApplyFilter()}
function dailyRefreshSummary(){const el=$('#daily-summary');if(!el)return;const students=dailyStudents().filter(x=>dailyGrade==='전체'||x.grade===dailyGrade),rows=students.map(s=>dailyEntry(s.id).data),o=rows.filter(x=>M.homeworkStatus(x)==='O').length,x=rows.filter(x=>M.homeworkStatus(x)==='X').length,scores=rows.filter(x=>x.wordScore!==null&&x.wordScore!=='').length,errors=students.filter(s=>dailyEntry(s.id).status==='error').length;el.innerHTML=`<span>학생 <b>${students.length}명</b></span>${['wordHomework','personalHomework'].map((key,i)=>`<span>${i?'개인숙제':'단어숙제'} <b class="text-green">O ${rows.filter(r=>r[key]==='O').length}</b> · <b class="text-red">X ${rows.filter(r=>r[key]==='X').length}</b></span>`).join('')}<span>단어시험 <b>${scores}/${rows.length}명 입력</b></span>${errors?`<span class="text-red">저장 실패 ${errors}건 · 해당 행에서 다시 저장</span>`:'<span class="muted">날짜별로 따로 보관됩니다.</span>'}`}
function dailyApplyFilter(){let visible=0;document.querySelectorAll('[data-daily-row]').forEach(row=>{const entry=dailyEntry(row.dataset.dailyRow,row.dataset.date),match=row.dataset.name.toLowerCase().includes(dailyQuery.toLowerCase())&&(!dailyOnlyMissing||dailyMissing(entry.data)||row.contains(document.activeElement)||['dirty','saving','error'].includes(entry.status));row.hidden=!match;if(match)visible++});const empty=$('#daily-filter-empty');if(empty)empty.hidden=visible>0}
function dailyPatch(id,date,patch,delay=0){scope(id);const entry=dailyEntry(id,date);Object.assign(entry.data,patch);entry.seq++;entry.status='dirty';entry.error='';dailyQueue.set(dailyKey(id,date),{id,date});dailyPaint(id,date);clearTimeout(dailyTimer);dailyTimer=setTimeout(dailyFlush,delay)}
async function dailyFlush(){if(dailyWorking)return;if(saving){clearTimeout(dailyTimer);dailyTimer=setTimeout(dailyFlush,150);return}dailyWorking=true;try{while(dailyQueue.size){const [key,{id,date}]=dailyQueue.entries().next().value;dailyQueue.delete(key);const entry=dailyEntry(id,date),seq=entry.seq,snapshot=M.clone(entry.data);entry.status='saving';dailyPaint(id,date);try{const payload={...snapshot,wordMax:Number(snapshot.wordMax),wordScore:snapshot.wordScore===null||snapshot.wordScore===''?null:Number(snapshot.wordScore)};await commit('일일 학습·숙제·단어시험 기록',n=>M.saveDailyRecord(n,id,date,payload),{render:false,quiet:true});if(entry.seq===seq){entry.data=M.clone(M.dailyRecord(d,id,date));entry.status='saved';entry.error=''}}catch(e){if(entry.seq===seq){entry.status='error';entry.error=e.message}toast(e.message+' 입력한 내용은 화면에 남겨두었습니다.')}dailyPaint(id,date)}}finally{dailyWorking=false;if(dailyQueue.size)dailyTimer=setTimeout(dailyFlush,100)}}
function dailyContext(el){const row=el.closest('[data-daily-row]');if(!row)throw Error('학생 행을 확인해 주세요.');return {id:row.dataset.dailyRow,date:row.dataset.date}}
on('daily-homework',el=>{const {id,date}=dailyContext(el);dailyPatch(id,date,{[el.dataset.field||'homework']:el.dataset.value||null})});
on('daily-row-save',el=>{const {id,date}=dailyContext(el);dailyPatch(id,date,{});return dailyFlush()});
on('daily-save-all',()=>{for(const [key,entry] of dailyDrafts){if(['dirty','error'].includes(entry.status)){const [date,id]=key.split('|');dailyQueue.set(key,{id,date})}}return dailyFlush()});
on('daily-grade',el=>{dailyGrade=el.dataset.grade;render()});
function dailyMove(days){const date=new Date(dailyDate+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+days);dailyDate=date.toISOString().slice(0,10);render()}
on('daily-prev',()=>dailyMove(-1));on('daily-next',()=>dailyMove(1));on('daily-today',()=>{dailyDate=M.today();render()});
on('daily-remove-unit',el=>{const {id,date}=dailyContext(el);dailyPatch(id,date,{units:dailyEntry(id,date).data.units.filter(u=>u.assignmentId!==el.dataset.assignment)});dailyPaint(id,date,true)});
on('daily-csv',()=>{staffOnly();download('thebom-test-daily-'+dailyDate+'.csv',csv([['날짜','학생','학년','오늘 학습','기존 숙제','단어숙제 수행','개인숙제 수행','오늘 단어숙제','오늘 개인숙제','단어시험 점수','만점','메모'],...visibleStudents().filter(s=>s.active).map(s=>{const r=M.dailyRecord(d,s.id,dailyDate);return [dailyDate,s.name,s.grade,r?.units.map(u=>M.book(d,d.assignments.find(a=>a.id===u.assignmentId)?.bookId)?.title+' Unit '+u.unit).join(' / ')||'',r?.homework??'',r?.wordHomework??'',r?.personalHomework??'',r?.wordHomeworkTask??'',r?.personalHomeworkTask??'',r?.wordScore??'',r?.wordMax??'',r?.note??'']})]),'text/csv;charset=utf-8')});
document.addEventListener('input',e=>{const el=e.target;if(el.hasAttribute('data-daily-search')){dailyQuery=el.value;dailyApplyFilter()}if(el.dataset.dailyField){const {id,date}=dailyContext(el),field=el.dataset.dailyField;dailyPatch(id,date,{[field]:el.validity?.badInput?'invalid':el.value},500)}});
document.addEventListener('change',e=>{const el=e.target;try{if(el.hasAttribute('data-daily-date')){if(el.value)dailyDate=el.value;render()}if(el.hasAttribute('data-daily-show-all')){dailyShowAll=el.checked;render()}if(el.hasAttribute('data-daily-missing')){dailyOnlyMissing=el.checked;dailyApplyFilter()}if(el.dataset.dailyUnit){const {id,date}=dailyContext(el);dailyPatch(id,date,{units:dailyEntry(id,date).data.units.map(u=>u.assignmentId===el.dataset.dailyUnit?{...u,unit:Number(el.value)}:u)})}if(el.hasAttribute('data-daily-add-book')&&el.value){const {id,date}=dailyContext(el),a=d.assignments.find(x=>x.id===el.value);scope(id);dailyPatch(id,date,{units:[...dailyEntry(id,date).data.units,{assignmentId:a.id,unit:M.nextUnit(d,a)}]});dailyPaint(id,date,true)}if(el.dataset.dailyField){clearTimeout(dailyTimer);dailyFlush()}}catch(err){toast(err.message)}});
document.addEventListener('focusout',e=>{if(e.target.closest('[data-daily-row]'))setTimeout(dailyApplyFilter,0)});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.dataset.dailyField==='wordScore'){e.preventDefault();const scores=[...document.querySelectorAll('[data-daily-row]:not([hidden]) [data-daily-field="wordScore"]')],index=scores.indexOf(e.target);e.target.blur();scores[index+1]?.focus()}});


let studentFreeReview=false,studentViewKey='';
function studentScheduleText(s){if(!Array.isArray(s.schedule))return '시간표 미설정';if(!s.schedule.length)return '정규 수업 없음';return [...s.schedule].sort((a,b)=>a.weekday-b.weekday||a.start.localeCompare(b.start)).map(x=>'일월화수목금토'[x.weekday]+' '+x.start+'~'+x.end).join(' · ')}
function editStudent(id){
 adminOnly();const s=student(id)||{name:'',grade:'초3',pin:'',teacherId:d.teachers[0]?.id||'',active:true,note:''},billing=s.billing||{enabled:false,amount:260000,day:5,startMonth:M.month()};
 open(id?'학생 정보 수정':'가상 학생 등록',`<div class="note">테스트용 정보만 입력해 주세요. 실제 학부모 연락처와 학생 개인정보는 운영 전환 전까지 입력하지 마세요.</div><h3 class="profile-section">👩‍🎓 학생 기본 정보</h3><div class="formgrid">${f('학생 이름','name',s.name,'text','required maxlength="40"')}${select('학년','grade',opts(['초1','초2','초3','초4','초5','초6','중1','중2','중3'],x=>x,x=>x,s.grade))}${f('입학일','entryDate',s.entryDate||'','date')}${f('학생 전화번호','studentPhone',s.phone||'','tel','placeholder="없으면 비워두세요" maxlength="25"')}${f('태블릿 출결번호 (4자리)','pin',s.pin,'text','required pattern="[0-9]{4}" maxlength="4" inputmode="numeric"')}${select('담당 교사','teacherId','<option value="">미지정</option>'+opts(d.teachers.filter(x=>x.active),x=>x.id,x=>x.name,s.teacherId))}</div><h3 class="profile-section">👨‍👩‍👧 보호자 연락처</h3><div class="formgrid">${f('보호자 이름','guardianName',s.guardianName||'','text','maxlength="40"')}${select('학생과의 관계','guardianRelation',opts(['','어머니','아버지','조부모','기타 보호자'],x=>x,x=>x||'선택',s.guardianRelation||''))}${f('학부모 전화번호 (알림 수신용)','guardianPhone',s.guardianPhone||'','tel','placeholder="예: 010-0000-0000" maxlength="25"')}${f('추가 보호자 전화번호 (선택)','guardianPhone2',s.guardianPhone2||'','tel','maxlength="25"')}</div><p class="muted">연락처는 알림·리포트 수신자 확인에 사용합니다. 이 테스트판에서 문자는 발송되지 않습니다.</p><h3 class="profile-section">📝 학생 단어시험</h3><label class="profile-check"><input type="checkbox" name="wordTestEnabled" ${s.wordTestEnabled?'checked':''}>단어시험 대상 · 학생 화면에서 점수 직접 입력</label>${f('기본 단어시험 문항 수 (제출할 때 변경 가능)','wordTestMax',s.wordTestMax||100,'number','min="1" max="1000" required')}<h3 class="profile-section">📅 학생 수업시간표</h3><p class="muted">정규 등원 요일과 시간을 지정하세요. 교재별 학습 요일과 별도로 학생의 등원 여부를 결정합니다.</p><label class="profile-check"><input type="checkbox" name="scheduleConfigured" ${Array.isArray(s.schedule)?'checked':''}>학생 시간표 지정</label><div id="student-schedule-rows">${(s.schedule||[]).map((slot,i)=>scheduleSlotHTML(slot,i)).join('')}</div>${btn('+ 수업 요일·시간 추가','student-add-slot','secondary','type="button"')}<p class="muted">시간표를 지정하지 않은 기존 학생은 누락 방지를 위해 ‘시간표 미설정’으로 표시합니다. 지정 후 수업이 없는 날은 오늘 목록에서 빠집니다.</p><h3 class="profile-section">₩ 월 수강료·자동 청구</h3><label class="profile-check"><input type="checkbox" name="autoBilling" ${billing.enabled?'checked':''}>매월 지정일에 청구 내역 자동 생성</label><div class="formgrid">${select('수강료 납부방법','billingPaymentMethod',opts([{v:'unset',n:'미설정'},{v:'payssam',n:'결제선생'},{v:'cash',n:'현금'},{v:'transfer',n:'계좌이체'}],x=>x.v,x=>x.n,billing.paymentMethod||'unset'))}${f('월 수강료 (원)','billingAmount',billing.amount||260000,'number','min="1" max="10000000" step="1"')}${f('매월 청구일 (1~31일)','billingDay',billing.day||5,'number','min="1" max="31" step="1"')}${f('자동 청구 시작 월','billingStartMonth',billing.startMonth||M.month(),'month')}</div><p class="muted">31일이 없는 달은 말일에 생성합니다. 청구 생성은 ‘미납’ 내역을 준비하는 기능이며 실제 결제나 자동이체를 실행하지 않습니다.</p>${area('학습 메모','note',s.note)}${id?select('재원 상태','active',`<option value="true" ${s.active?'selected':''}>재원</option><option value="false" ${s.active?'':'selected'}>퇴원 (기록 유지)</option>`):''}`,
 v=>{const pin=v.get('pin'),newId=id||M.uid(),wordTestMax=Number(v.get('wordTestMax'));if(!Number.isInteger(wordTestMax)||wordTestMax<1||wordTestMax>1000)throw Error('단어시험 만점은 1~1000 사이로 입력해 주세요.');if(d.students.some(x=>x.id!==id&&x.pin===pin))throw Error('이미 사용하는 출결번호입니다.');const name=v.get('name').trim();if(!name||!/^\d{4}$/.test(pin))throw Error('학생 이름과 4자리 출결번호를 확인해 주세요.');const schedule=v.has('scheduleConfigured')?[...modal.querySelectorAll('[data-schedule-slot]')].map(el=>({weekday:Number(el.querySelector('[data-slot-day]').value),start:el.querySelector('[data-slot-start]').value,end:el.querySelector('[data-slot-end]').value})):undefined;const info={entryDate:v.get('entryDate'),phone:v.get('studentPhone').trim(),guardianName:v.get('guardianName').trim(),guardianRelation:v.get('guardianRelation'),guardianPhone:v.get('guardianPhone').trim(),guardianPhone2:v.get('guardianPhone2').trim(),schedule,billing:{enabled:v.has('autoBilling'),paymentMethod:v.get('billingPaymentMethod'),amount:Number(v.get('billingAmount')),day:Number(v.get('billingDay')),startMonth:v.get('billingStartMonth')}};return commit(id?'학생 정보·수업시간표 수정':'학생 등록',n=>{if(!id)n.students.push({id:newId});Object.assign(n.students.find(x=>x.id===newId),{name,wordTestEnabled:v.has('wordTestEnabled'),wordTestMax,grade:v.get('grade'),pin,teacherId:v.get('teacherId'),note:v.get('note').trim(),active:v.get('active')!=='false'});M.saveStudentDetails(n,newId,info);M.generateDueInvoices(n,M.today())})});
}
function scheduleSlotHTML(slot,index){return `<div class="schedule-slot" data-schedule-slot><select data-slot-day aria-label="수업 요일 ${index+1}">${opts([0,1,2,3,4,5,6],x=>x,x=>'일월화수목금토'[x]+'요일',slot.weekday)}</select><input type="time" data-slot-start value="${E(slot.start)}" aria-label="수업 시작 ${index+1}"><span>~</span><input type="time" data-slot-end value="${E(slot.end)}" aria-label="수업 종료 ${index+1}"><button class="quiet" type="button" data-action="student-remove-slot">삭제</button></div>`}
on('student-add-slot',()=>{const target=$('#student-schedule-rows'),index=target.children.length;target.insertAdjacentHTML('beforeend',scheduleSlotHTML({weekday:1,start:'15:00',end:'16:00'},index));$('[name="scheduleConfigured"]').checked=true;dirty=true});on('student-remove-slot',el=>{el.closest('[data-schedule-slot]').remove();dirty=true});
function dailyStudents(){return visibleStudents().filter(s=>s.active&&(dailyShowAll||M.isClassDay(d,s,dailyDate)!==false))}
function billingSettingsHTML(){return `<div class="card"><div class="row between"><h2>학생별 월 청구 설정</h2>${btn('지금 자동 청구 확인','billing-sync','secondary')}</div><p class="muted">학생 정보에서 수강료와 매월 청구일을 설정하세요. 같은 학생·같은 월의 청구를 중복 생성하지 않습니다.</p><div class="table-wrap"><table><thead><tr><th>학생</th><th>보호자 연락처</th><th>월 수강료</th><th>청구일</th><th>자동 청구</th><th></th></tr></thead><tbody>${d.students.filter(s=>s.active).map(s=>`<tr><td>${E(s.name)}</td><td>${E(s.guardianPhone||'미등록')}</td><td>${s.billing?.enabled?money(s.billing.amount):'미설정'}</td><td>${s.billing?.enabled?'매월 '+s.billing.day+'일':'—'}</td><td>${badge(s.billing?.enabled?'사용':'미사용',s.billing?.enabled?'':'amber')}</td><td>${btn('학생 정보에서 설정',`student-edit:${s.id}`,'quiet')}</td></tr>`).join('')}</tbody></table></div><p class="muted">자동 청구는 미납 장부를 생성합니다. 실제 수납 완료는 결제 내역이 확인된 뒤 기록합니다.</p></div>`}
on('billing-sync',async()=>{adminOnly();if(cloud){const r=await fetch('/api/billing/run',{method:'POST'});if(!r.ok)throw Error('자동 청구를 확인할 수 없습니다.');const result=await r.json();await boot();toast('자동 청구 '+result.created+'건을 확인했습니다.')}else{let count=0;await commit('자동 청구 확인',n=>count=M.generateDueInvoices(n,M.today()));toast('새 청구 '+count+'건 · 실제 결제 없음')}});
on('student-free-review',()=>{studentFreeReview=true;render()});

let noticeSelection=new Set(),noticeShowFuture=true;
const paymentMethodName=method=>({payssam:'결제선생',cash:'현금',transfer:'계좌이체',unset:'미설정'}[method]||'미설정');
function noticeOverview(){if(role!=='admin')return '';const states=d.invoices.map(i=>M.tuitionNoticeState(d,i)),count=states.filter(s=>s.eligible).length,unconfigured=states.filter(s=>s.reason==='납부방법 미설정').length;return `<div class="card notice-overview"><div><h2>💬 현금·계좌이체 수강료 안내</h2><p>청구일이 된 안내 대상 <b>${count}건</b>${unconfigured?' · 납부방법 미설정 '+unconfigured+'건':''}</p><span class="muted">결제선생 대상은 별도 분리 · 납부 완료·취소 건은 제외</span></div>${btn('대상 선택·안내 준비','notice-open','')}</div>`}
function tuitionNoticesHTML(){
 const invoices=d.invoices.filter(i=>i.month===invoiceMonth&&!i.cancelled&&i.amount>M.paid(i)&&(noticeShowFuture||i.due<=M.today()));
 const missing=d.students.filter(s=>s.active&&!d.invoices.some(i=>i.studentId===s.id&&i.month===invoiceMonth));
 const eligible=invoices.filter(i=>M.tuitionNoticeState(d,i).eligible),selected=eligible.filter(i=>noticeSelection.has(i.id)).length;
 return `<section class="card" id="tuition-notices"><div class="row between"><h2>💬 수강료 안내 대상 선택</h2>${btn('선택한 학부모 안내 준비','notice-preview','',selected?'':'disabled')}</div><p>조회 월 <b>${E(invoiceMonth)}</b> · 선택 가능 <b>${eligible.length}건</b> · 선택 <b>${selected}건</b></p><p class="muted">청구일 전 내역도 기본으로 표시합니다. 체크할 수 없는 경우 아래 이유를 확인해 주세요. 현금·계좌이체 + 보호자 연락처 + 청구일 도달 + 미납 조건을 갖추면 선택할 수 있어요.</p><div class="row between" style="margin:12px 0"><label class="daily-filter"><input type="checkbox" data-notice-future ${noticeShowFuture?'checked':''}>청구일 전 내역도 보기</label>${btn('안내 가능 대상 전체 선택','notice-select-all','secondary',eligible.length?'':'disabled')}</div><div class="table-wrap"><table><thead><tr><th>선택</th><th>학생</th><th>납부방법</th><th>청구일</th><th>미납 금액</th><th>안내 상태·필요한 설정</th><th></th></tr></thead><tbody>${invoices.map(i=>{const s=student(i.studentId),n=M.tuitionNoticeState(d,i);const issues=[!['cash','transfer','payssam'].includes(n.method)?'납부방법 미설정':'',!s?.guardianPhone?'보호자 연락처 미등록':'',i.due>M.today()?i.due+'부터 선택 가능':''].filter(Boolean);return `<tr><td><input type="checkbox" aria-label="${E(s?.name)} 수강료 안내 선택" data-notice-id="${E(i.id)}" ${noticeSelection.has(i.id)&&n.eligible?'checked':''} ${n.eligible?'':'disabled'}></td><td>${E(s?.name)}</td><td>${E(paymentMethodName(n.method))}</td><td>${E(i.due)}</td><td>${money(n.balance)}</td><td>${badge(n.eligible?'선택 가능':n.reason,n.eligible?'':'amber')}<div class="muted">${E(issues.join(' · '))}</div></td><td>${n.draft?btn('초안 확인',`notification:${n.draft.id}`,'quiet'):btn('학생 정보·납부방법 설정',`student-edit:${s?.id}`,'quiet')}</td></tr>`}).join('')}</tbody></table>${!invoices.length?'<div class="empty">이 월에 표시할 미납 청구가 없습니다. 청구 월을 확인하거나 아래에서 청구 내역을 등록해 주세요. 수납 완료·취소 내역은 안내 대상에서 제외됩니다.</div>':''}</div>${missing.length?`<h3 style="margin-top:20px">아직 청구 내역이 없는 학생 ${missing.length}명</h3><p class="muted">학생 등록만으로는 수강료 청구가 만들어지지 않습니다. 자동 청구는 지정일에 생성되며, 먼저 준비하려면 청구를 직접 등록하세요.</p><div class="table-wrap"><table><thead><tr><th>학생</th><th>납부방법</th><th>청구 설정</th><th></th></tr></thead><tbody>${missing.map(s=>`<tr><td>${E(s.name)}</td><td>${E(paymentMethodName(s.billing?.paymentMethod||'unset'))}</td><td>${s.billing?.enabled?'매월 '+E(s.billing.day)+'일 · 시작 '+E(s.billing.startMonth):'자동 청구 미설정'}</td><td>${btn('학생 정보 설정',`student-edit:${s.id}`,'quiet')} ${btn('청구 등록',`notice-invoice:${s.id}`,'secondary')}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="note" style="margin-top:14px">카카오톡 연동 전에는 수신자·문구 확인과 초안 저장·복사까지 가능합니다. 실제 전송은 하지 않으며, ‘초안 준비’가 ‘발송 완료’를 뜻하지 않습니다.</div></section>`
}
on('notice-invoice',id=>{actions['add-invoice']();const s=student(id);modal.querySelector('[name="studentId"]').value=id;if(s?.billing?.amount)modal.querySelector('[name="amount"]').value=s.billing.amount;if(s?.billing?.day)modal.querySelector('[name="due"]').value=M.billingDueDate(invoiceMonth,s.billing.day)});

on('notice-open',()=>{const first=d.invoices.filter(i=>M.tuitionNoticeState(d,i).eligible).sort((a,b)=>a.due.localeCompare(b.due))[0];if(first)invoiceMonth=first.month;view='tuition';render();$('#tuition-notices')?.scrollIntoView({block:'start'})});
on('notice-select-all',()=>{noticeSelection=new Set(d.invoices.filter(i=>i.month===invoiceMonth&&M.tuitionNoticeState(d,i).eligible).map(i=>i.id));render()});
on('notice-preview',()=>{adminOnly();const invoices=d.invoices.filter(i=>noticeSelection.has(i.id)&&i.month===invoiceMonth&&M.tuitionNoticeState(d,i).eligible);if(!invoices.length)throw Error('안내 가능한 현금·계좌이체 청구를 선택해 주세요.');const temporary=M.clone(d);M.prepareTuitionNotices(temporary,invoices.map(i=>i.id));open('선택한 학부모 수납 안내 확인',`<div class="note">${invoices.length}건의 안내를 준비합니다. 카카오톡 연동 전이므로 실제 발송하지 않습니다.</div>${invoices.map(i=>{const s=student(i.studentId),draft=temporary.notifications.find(x=>x.invoiceId===i.id&&x.purpose==='tuition_reminder');return `<div class="notice-preview-item"><h3>${E(s.name)} · ${E(paymentMethodName(M.tuitionNoticeState(d,i).method))}</h3><p class="muted">수신 보호자 ${E(s.guardianName||'보호자')} · ${E(s.guardianPhone)}</p>${area('수납 안내 문구','noticeBody_'+i.id,draft.body)}</div>`}).join('')}<button type="button" disabled>카카오 연동 후 선택 전송</button>`,async v=>{const bodies=Object.fromEntries(invoices.map(i=>[i.id,v.get('noticeBody_'+i.id)]));await commit('선택한 현금·이체 수납 안내 초안 준비',n=>M.prepareTuitionNotices(n,invoices.map(i=>i.id),M.today(),bodies));noticeSelection.clear();view='notifications';render()},'선택 안내 초안 저장')});
document.addEventListener('change',e=>{if(e.target.dataset.noticeId){e.target.checked?noticeSelection.add(e.target.dataset.noticeId):noticeSelection.delete(e.target.dataset.noticeId);render()}if(e.target.hasAttribute('data-notice-future')){noticeShowFuture=e.target.checked;render()}});

for(const kind of ['word','reading'])on('audio-remove-'+kind,()=>{delete uploaded[kind+'Url'];uploaded[kind+'Data']=null;const input=$('[data-audio="'+kind+'Url"]');if(input)input.value='';const url=$('[name="'+kind+'Url"]').value;$('#preview-'+kind).innerHTML=url?audioPlayer(url,'주소 음원 미리듣기'):'<p class="muted">저장하면 업로드 파일이 제거됩니다.</p>';dirty=true});
document.addEventListener('input',e=>{const kind=e.target.dataset.materialUrl;if(!kind)return;try{const url=M.materialURL(e.target.value);delete uploaded[kind+'Url'];uploaded[kind+'Data']=null;$('#preview-'+kind).innerHTML=url?(url.startsWith('https:')&&/\.(html?|aspx?|php)$/i.test(new URL(url).pathname)?'<p class="muted">자료실 페이지 주소입니다. 저장하면 ‘자료실 열기’ 링크로 연결됩니다.</p>':audioPlayer(url,'주소 음원 미리듣기')):'<p class="muted">직접 재생 음원이 없습니다.</p>';}catch{ $('#preview-'+kind).textContent='HTTPS 음원 주소를 확인해 주세요.' }});
document.addEventListener('loadedmetadata',e=>{if(e.target.tagName!=='AUDIO')return;const status=e.target.parentElement.querySelector('.audio-status');if(status)status.textContent='음원 연결 확인 · 재생 버튼을 눌러 들어보세요.'},true);
document.addEventListener('error',e=>{if(e.target.tagName!=='AUDIO')return;const status=e.target.parentElement.querySelector('.audio-status');if(status)status.textContent='음원을 불러오지 못했어요. 주소·공개 권한·파일 형식을 확인해 주세요. 자료실 웹페이지라면 ‘자료실 열기’로 연결해 주세요.'},true);
function attendancePreparation(){const candidates=M.attendanceCandidates(d,attDate);return `<div class="card"><h2>미등원·결석 안내 준비</h2><p class="muted">학생 시간표 기준 수업 시작 10분 후 미등원을 표시합니다. 등원 기록이 있거나 수업일이 아니면 제외합니다. 결석은 선생님이 결석으로 기록한 학생만 표시합니다. 실제 알림톡은 발송되지 않습니다.</p>${candidates.map(x=>`<div class="row between activity"><span><b>${E(student(x.studentId)?.name)}</b> · ${x.type==='absence'?'결석 확인':'미등원 확인'} · ${E(x.start)} ${E(x.reason)}</span>${btn('안내 초안 준비',`attendance-notice:${x.studentId}:${x.type}`,'secondary',x.ready?'':'disabled')}</div>`).join('')||'<p class="empty">현재 안내 대상이 없습니다. 학생 정보에 수업시간표가 지정되어 있어야 합니다.</p>'}</div>`}
function reportCommentEditor(id){const r=d.reports.find(x=>x.id===id);scope(r.studentId);open('리포트 코멘트 · AI 초안 활용',`<div class="note">AI 자동 호출은 아직 연결되지 않았습니다. ‘AI 요청문 복사’로 기록을 가져가 작성한 결과를 아래에 붙여넣고 확인하세요. 요청문에는 학생 이름·전화번호·일일 메모를 포함하지 않습니다. 관찰 메모에도 개인정보를 넣지 마세요.</div>${area('선생님 관찰 메모 (AI 요청문용, 선택)','aiObservation','')}<div class="row">${btn('기록 기반 초안 만들기','report-record-draft','secondary','type="button"')}${btn('AI 요청문 복사','report-copy-ai','secondary','type="button"')}</div>${area('AI 작성 결과 붙여넣기','aiResult','')}${btn('AI 결과를 코멘트에 적용','report-apply-ai','secondary','type="button"')}${area('선생님 코멘트','comment',r.comment)}${area('가정 학습 안내 (선택 · 비워두면 리포트에 표시하지 않음)','homework',r.homework||'')}${f('녹음 제목 (선택)','recordingTitle',r.recordingTitle||'우리 아이 녹음 듣기','text','maxlength="100"')}${f('아이 녹음 URL (선택)','recordingUrl',r.recordingUrl||'','url','placeholder="https://…"')}<input type="hidden" name="commentSource" value="${E(r.commentSource||'manual')}"><input type="hidden" name="reportId" value="${E(id)}"><details><summary>이전 코멘트 (${(r.commentHistory||[]).length}개)</summary>${(r.commentHistory||[]).map((h,i)=>`<div><p style="white-space:pre-wrap">${E(h.comment)}</p>${btn('이 버전을 편집칸에 가져오기','report-restore-history','secondary',`type="button" data-index="${i}"`)}</div>`).reverse().join('')||'<p>이전 버전이 없습니다.</p>'}</details><p class="muted">저장한 뒤 내용을 검토하고 ‘코멘트 검토 확정’을 눌러 주세요. 다시 수정하면 재검토 상태로 돌아갑니다.</p>`,v=>commit('월간 코멘트 수정 (이전 버전 보존)',n=>M.saveReportComment(n,id,v.get('comment'),v.get('homework'),v.get('commentSource'),{url:v.get('recordingUrl'),title:v.get('recordingTitle')})),'코멘트 저장')}
on('report-record-draft',()=>{const id=modal.querySelector('[name="reportId"]').value;modal.querySelector('[name="comment"]').value=M.reportRecordDraft(d.reports.find(x=>x.id===id));modal.querySelector('[name="commentSource"]').value='record';dirty=true});
on('report-copy-ai',async()=>{const id=modal.querySelector('[name="reportId"]').value,r=d.reports.find(x=>x.id===id);await navigator.clipboard.writeText(M.reportAIPrompt(r,modal.querySelector('[name="aiObservation"]').value));toast('학생 식별 정보를 제외한 AI 요청문을 복사했습니다. ChatGPT 등에 붙여넣어 초안을 작성해 주세요.')});
on('report-apply-ai',()=>{const value=modal.querySelector('[name="aiResult"]').value.trim();if(!value||value.length>6000)throw Error('AI 작성 결과를 6000자 이내로 붙여넣어 주세요.');modal.querySelector('[name="comment"]').value=value;modal.querySelector('[name="commentSource"]').value='ai_assisted';dirty=true});

function messagingPreparationHTML(){const config=d.messagingPreparation,approved=M.messageTemplateTypes.filter(x=>config?.templates?.[x.id]?.status==='approved'&&config?.templates?.[x.id]?.id).length;return `<div class="card"><div class="row between"><h2>솔라피 연결 준비</h2>${btn('채널·템플릿 ID 기록','messaging-preparation')}</div><p>학원 카카오 채널: <a href="https://pf.kakao.com/_Cxlxnvn" target="_blank" rel="noopener noreferrer">더봄어학원 ↗</a></p><p>승인·ID 기록 ${approved}/${M.messageTemplateTypes.length}개 · 실제 발송 비활성화</p><p class="muted">원장님이 심사 결과를 기록하는 준비 화면입니다. 솔라피 API로 확인한 결과가 아닙니다. API Key·Secret은 이 화면에 입력하지 마세요. 결제선생은 API 상담 회신 대기 상태입니다.</p></div>`}
on('messaging-preparation',()=>{adminOnly();const config=d.messagingPreparation;open('솔라피 채널·템플릿 준비',`<div class="note">솔라피에 표시되는 채널 ID와 템플릿 ID만 기록하세요. 비밀번호·API 비밀키 입력란이 아닙니다. 저장해도 발송되지 않습니다.</div>${f('솔라피 채널 ID (channelId / pfId)','channelId',config?.channelId||'','text','maxlength="100"')}${M.messageTemplateTypes.map(x=>`<h3>${E(x.name)}</h3><div class="formgrid">${f('템플릿 ID',x.id+'Id',config?.templates?.[x.id]?.id||'','text','maxlength="100"')}${select('심사 상태',x.id+'Status',opts([{v:'pending',n:'심사 대기'},{v:'approved',n:'승인'},{v:'rejected',n:'반려'}],y=>y.v,y=>y.n,config?.templates?.[x.id]?.status||'pending'))}</div>`).join('')}`,v=>commit('솔라피 연결 준비 정보 기록',n=>M.saveMessagingPreparation(n,{channelId:v.get('channelId').trim(),templates:Object.fromEntries(M.messageTemplateTypes.map(x=>[x.id,{id:v.get(x.id+'Id').trim(),status:v.get(x.id+'Status')}]))})))});

on('report-restore-history',el=>{const r=d.reports.find(x=>x.id===modal.querySelector('[name="reportId"]').value),h=r.commentHistory?.[Number(el.dataset.index)];if(!h)throw Error('이전 코멘트를 찾을 수 없습니다.');modal.querySelector('[name="comment"]').value=h.comment;modal.querySelector('[name="homework"]').value=h.homework;modal.querySelector('[name="commentSource"]').value=h.source||'manual';dirty=true});
const parentPreviewCache=new Map(),parentLinkCache=new Map();
function parentPreviewURL(kind,item){return '/sandbox/parent-preview.html?kind='+encodeURIComponent(kind)+'&id='+encodeURIComponent(item.id)+(cloud?'&cloud=1':'')}
function parentControls(kind,item){const link=parentLinkCache.get(kind+':'+item.id);return `<div class="parent-actions no-print"><a class="parent-link-button" href="${E(parentPreviewURL(kind,item))}" target="_blank" rel="noopener noreferrer">${kind==='report'?'리포트':'공지사항'} 웹페이지 미리보기 ↗</a>${cloud?btn('확인 링크 생성 (30일)',`parent-create:${kind}:${item.id}`)+btn('기존 링크 회수',`parent-revoke:${kind}:${item.id}`,'quiet'):'<span class="muted">온라인 테스트판에서 확인 링크를 생성할 수 있습니다.</span>'}${link?`<p><a href="${E(link.url)}" target="_blank" rel="noopener noreferrer">생성한 확인 페이지 열기 ↗</a> · 만료 ${E(link.expiresAt.slice(0,10))}</p>`:''}<p class="muted">현재는 원장님만 접근하는 비공개 테스트 링크입니다. 학부모 공개 연결은 별도 배포 후 활성화합니다. 새 링크 생성 시 이전 링크가 회수되며, 수정한 내용을 반영하려면 다시 생성해 주세요.</p></div>`}
async function manageParentLink(kind,id,action){staffOnly();if(kind==='report')scope(d.reports.find(x=>x.id===id)?.studentId);if(!cloud)throw Error('온라인 테스트판에서 링크를 준비해 주세요.');const response=await fetch('/api/parent-links',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,id,action})});const result=await response.json();if(!response.ok)throw Error(result.error||'링크를 처리하지 못했습니다.');if(action==='create')parentLinkCache.set(kind+':'+id,{...result,url:new URL(result.url,location.origin).href});else parentLinkCache.delete(kind+':'+id);render();toast(action==='create'?'비공개 테스트 확인 링크를 생성했습니다.':'이 문서의 기존 링크를 회수했습니다.')}
function announcements(){staffOnly();const items=(d.announcements||[]).filter(x=>!x.archived);return head('ACADEMY ANNOUNCEMENTS','공지사항','짧은 안내와 상세 공지 페이지를 따로 준비해요.',btn('+ 공지사항 작성','announcement-new',''))+`<p class="note">일반 안내는 짧은 알림 문구로, 긴 공지는 ‘공지사항 확인하기’ 버튼과 상세 페이지로 준비할 수 있습니다. 솔라피 연결·해당 템플릿 승인 전에는 실제 발송되지 않습니다.</p>${items.map(n=>`<section class="card"><div class="row between"><h2>${E(n.title)}</h2>${btn('수정',`announcement-edit:${n.id}`)}</div><p class="muted">알림 문구</p><p class="notice-summary">${E(n.summary)}</p><details><summary>상세 내용</summary><p style="white-space:pre-wrap">${E(n.body)}</p></details>${parentControls('notice',n)}<div class="row">${btn('짧은 알림 초안 준비',`announcement-draft:${n.id}:short`)}${btn('상세 링크 알림 초안 준비',`announcement-draft:${n.id}:link`)}</div></section>`).join('')||'<div class="card empty">공지사항을 작성해 주세요.</div>'}`}
function announcementEditor(id){staffOnly();const n=d.announcements?.find(x=>x.id===id);open(id?'공지사항 수정':'공지사항 작성',`${f('공지 제목','title',n?.title||'','text','required maxlength="100"')}${area('톡에 보낼 짧은 안내 (800자 이내)','summary',n?.summary||'')}${area('상세 웹페이지 내용','body',n?.body||'')}<p class="muted">기존 공지는 수정 이력이 보존됩니다. 링크를 만든 뒤 수정했다면 링크를 다시 생성해 주세요.</p>`,v=>commit('공지사항 저장 (이전 내용 보존)',next=>M.saveAnnouncement(next,id,{title:v.get('title'),summary:v.get('summary'),body:v.get('body')})))}
function announcementRecipients(id,mode){staffOnly();const n=d.announcements.find(x=>x.id===id),link=parentLinkCache.get('notice:'+id);if(mode==='link'&&!link)throw Error('‘확인 링크 생성’을 먼저 눌러 주세요. 현재는 비공개 테스트 링크입니다.');open('공지사항 알림 대상 선택',`<h3>${E(n.title)}</h3><p style="white-space:pre-wrap">${E(n.summary)}</p><p class="note">${mode==='link'?'‘공지사항 확인하기’ 버튼을 포함한 초안':'짧은 내용만 담은 초안'}을 저장합니다. 실제 전송되지 않습니다.</p>${visibleStudents().filter(s=>s.active).map(s=>`<label class="profile-check"><input type="checkbox" name="recipient" value="${E(s.id)}" ${s.guardianPhone?'':'disabled'}>${E(s.name)} · ${E(s.guardianPhone||'보호자 연락처 미등록')}</label>`).join('')}`,async v=>{await commit('공지사항 선택 알림 초안',next=>M.prepareAnnouncementNotices(next,id,v.getAll('recipient'),mode,link?.url||''));view='notifications';render()},'선택 대상 초안 저장')}
on('announcement-new',()=>announcementEditor());

let membershipRows=[];
function accountAccessHTML(){return `<section class="card"><div class="row between"><h2>실제 계정 권한 관리</h2>${btn('등록 계정 새로고침','memberships-refresh')}${btn('+ 교사·학생 계정 연결','membership-new')}</div><p class="muted">원장은 전체 관리, 교사는 담당 학생의 수업 기록, 학생은 본인의 학습 체크만 사용할 수 있습니다. 화면 시연 선택은 실제 권한을 바꾸지 않습니다. 계정 연결은 사이트 초대나 외부 공개를 실행하지 않습니다.</p>${membershipRows.map(x=>`<div class="row between activity"><span>${E(x.email)} · ${x.role==='teacher'?'교사':'학생'} · ${E(x.entity_id)} · ${x.active?'활성':'중지'}</span>${x.active?`<button class="quiet" data-action="membership-revoke" data-email="${E(x.email)}">접근 중지</button>`:''}</div>`).join('')||'<p class="muted">등록 계정을 새로고침해 주세요. 다른 사람에게 접근 권한을 주기 전 사이트 초대 설정도 별도로 확인해야 합니다.</p>'}<hr><h3>온라인 음원 저장·재생 점검</h3><p class="muted">개인 음원 대신 짧은 검증용 WAV 파일로 실제 저장·읽기·구간 재생·다른 계정 차단을 점검한 뒤 검증용 파일만 정리합니다.</p>${btn('온라인 음원 점검 실행','audio-diagnostic')}<div id="audio-diagnostic-result"></div></section>`}
on('memberships-refresh',async()=>{adminOnly();if(!cloud)throw Error('온라인 테스트판에서 사용할 수 있습니다.');const r=await fetch('/api/memberships',{cache:'no-store'});if(!r.ok)throw Error('계정 권한을 조회할 수 없습니다.');membershipRows=(await r.json()).members;render()});
on('membership-new',()=>{adminOnly();if(!cloud)throw Error('온라인 테스트판에서 사용할 수 있습니다.');open('로그인 계정과 학원 역할 연결',`${f('로그인에 사용할 이메일','email','','email','required')}${select('역할','membershipRole','<option value="teacher">교사</option><option value="student">학생</option>')}${select('연결할 교사','teacherEntity',opts(d.teachers.filter(x=>x.active),x=>x.id,x=>x.name))}${select('연결할 학생','studentEntity',opts(d.students.filter(x=>x.active),x=>x.id,x=>x.name))}<p class="note">선택한 역할에 해당하는 교사 또는 학생만 연결됩니다. 원장 권한은 이 화면에서 부여하지 않습니다. 실제 사이트 방문자 초대는 실행하지 않습니다.</p>`,async v=>{const type=v.get('membershipRole');const r=await fetch('/api/memberships',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'save',email:v.get('email'),role:type,entityId:v.get(type==='teacher'?'teacherEntity':'studentEntity')})});if(!r.ok)throw Error('계정 연결에 실패했습니다. 이메일과 연결 대상을 확인해 주세요.');await actions['memberships-refresh']()},'계정 권한 저장')});
on('membership-revoke',async el=>{adminOnly();const r=await fetch('/api/memberships',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'revoke',email:el.dataset.email})});if(!r.ok)throw Error('접근을 중지하지 못했습니다.');await actions['memberships-refresh']()});
on('audio-diagnostic',async()=>{adminOnly();if(!cloud)throw Error('온라인 테스트판에서 실행해 주세요.');$('#audio-diagnostic-result').textContent='실제 저장소를 점검하고 있습니다…';const r=await fetch('/api/diagnostics/audio',{method:'POST'});const result=await r.json();$('#audio-diagnostic-result').innerHTML=`<p>${result.ok?'전체 점검 통과':'점검을 완료하지 못했습니다.'}</p>${(result.checks||[]).map(x=>`<p>${x.passed?'✓':'✕'} ${E(x.name)}</p>`).join('')}`});

let backupPanel=null;
const sizeMB=n=>(n/1024/1024).toFixed(1)+'MB';
function backupSettingsHTML(){const storage=backupPanel?.storage;return `<section class="card"><div class="row between"><h2>자료 보존·백업·저장 용량</h2>${btn('저장 현황 새로고침','backups-refresh')}</div><p class="note">온라인 교재·음원은 프로그램 코드와 분리해 저장합니다. 기존 자료를 가상 교재로 자동 교체하지 않습니다. 전체 원본을 등록하기 전 용량을 확인하고 ZIP 백업을 내려받아 별도로 보관하세요.</p>${storage?`<p><b>음원 ${sizeMB(storage.usedBytes)} / ${sizeMB(storage.limitBytes)}</b> · ${storage.fileCount}개 보관 · 파일당 ${sizeMB(storage.maxFileBytes)}</p><p>교재 ${storage.summary.books}권 · Unit 자료 ${storage.summary.materials}건 · 연결 음원 ${storage.linkedFiles}개 · 기록 데이터 ${sizeMB(storage.recordsBytes)}</p>${storage.missingFiles.length?'<p class="note">누락된 음원이 있습니다. 대량 등록 전에 연결을 확인해 주세요.</p>':'<p class="muted">저장된 음원 파일과 현재 Unit 연결을 확인했습니다.</p>'}`:'<p class="muted">온라인 테스트판에서 현재 사용량과 백업을 조회할 수 있습니다. 현재 음원 총량은 100MB이며 대량 등록용 무제한 저장소가 아닙니다.</p>'}<div class="row">${btn('현재 자료 서버 백업','backup-save')}${btn('교재·음원 원본 ZIP 내려받기','backup-export','')}${btn('기록 JSON 내려받기','export-json')}</div><p class="muted">저장 전 상태를 자동으로 보관하며 자동 백업은 최근 20개를 유지하고, 직접 저장한 서버 백업은 별도로 보존합니다. ZIP에는 저장한 교재·학습 기록과 업로드 음원 원본이 포함됩니다. 구글 드라이브·출판사 등 외부 자료는 링크만 포함됩니다. ZIP 자동 가져오기는 아직 제공하지 않습니다.</p>${backupPanel?.backups?.length?`<h3>서버 백업 복구</h3>${backupPanel.backups.map(b=>`<div class="row between activity"><span>${b.pinned?'직접 보관 · ':'자동 · '}버전 ${b.revision} · ${E(new Date(b.savedAt).toLocaleString('ko-KR'))} · 교재 ${b.summary?.books??'—'}권</span>${btn('복구 내용 확인',`backup-restore:${b.revision}`,'secondary')}</div>`).join('')}`:''}</section>`}
on('backups-refresh',async()=>{adminOnly();if(!cloud)throw Error('온라인 테스트판에서 조회해 주세요.');const r=await fetch('/api/backups',{cache:'no-store'});if(!r.ok)throw Error('백업과 저장 용량을 조회하지 못했습니다.');backupPanel=await r.json();render()});
on('backup-save',async()=>{adminOnly();if(!cloud)throw Error('온라인 테스트판에서 백업해 주세요.');const r=await fetch('/api/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'save'})});if(!r.ok)throw Error('백업을 저장하지 못했습니다. 먼저 현재 변경 내용을 저장해 주세요.');await actions['backups-refresh']();toast('현재 자료를 서버에 백업했습니다.')});
on('backup-export',async()=>{adminOnly();if(!cloud)throw Error('온라인 테스트판에서 내려받아 주세요.');toast('ZIP 백업을 준비하고 있습니다. 파일 크기에 따라 시간이 걸릴 수 있습니다.');const r=await fetch('/api/backups/export',{method:'POST'});if(!r.ok)throw Error('백업을 만들지 못했습니다. 누락 음원과 로그인 상태를 확인해 주세요.');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='thebom-library-backup-'+M.today()+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('ZIP 백업 내려받기를 시작했습니다. 내려받은 파일을 별도로 보관해 주세요.')});
async function previewBackupRestore(revision){adminOnly();const response=await fetch('/api/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'preview',revision})});if(!response.ok)throw Error('백업을 불러오지 못했습니다.');const info=await response.json();open('백업 복구 전 확인',`<p class="note">현재 자료가 버전 ${revision} 시점으로 돌아갑니다. 현재 상태를 먼저 자동 백업하며 업로드 음원 원본은 지우지 않습니다. 다른 기기에서 수정 중이면 복구하지 마세요.</p><p>교재 ${info.stateSummary.books}권 · 학생 ${info.stateSummary.students}명 · Unit 자료 ${info.stateSummary.materials}건</p>${f('진행하려면 복구라고 입력해 주세요','confirm','','text','required')}`,async v=>{if(v.get('confirm')!=='복구')throw Error('복구라고 입력해 주세요.');const r=await fetch('/api/backups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'restore',revision,expectedRevision:d.revision,confirm:'복구'})});if(!r.ok){const error=await r.json();throw Error(error.error==='revision_conflict'?'다른 수정이 있습니다. 새로고침 후 확인해 주세요.':error.error||'복구하지 못했습니다.')}await boot();await actions['backups-refresh']()},'이 버전으로 복구')}

function bookTrashHTML(){const deleted=d.books.filter(b=>b.deletedAt);return `<details class="book-trash" style="margin-top:22px;border-top:1px solid var(--line);padding-top:16px"><summary>🗑️ 교재 휴지통 (${deleted.length}권)</summary><p class="muted">삭제한 교재의 과정·자료·기존 학습 기록은 보존됩니다. 복원하면 다시 사용할 수 있습니다.</p>${deleted.map(b=>`<div class="lab-item"><b>${E(b.title)}</b>${btn('복원',`book-restore:${b.id}`,'secondary')}</div>`).join('')||'<p class="muted">휴지통이 비어 있습니다.</p>'}</details>`}
function confirmBookTrash(id){adminOnly();const b=M.book(d,id);if(d.assignments.some(a=>a.bookId===id&&!a.archived))throw Error('현재 학생에게 배정된 교재입니다. 먼저 해당 배정을 보관한 뒤 삭제해 주세요.');open('교재 삭제 확인',`<p><b>${E(b.title)}</b> 교재를 휴지통으로 이동할까요?</p><p class="note">교재 라이브러리에서 숨기며, 교재의 학습 과정·음원 연결·기존 기록은 지우지 않습니다. 교재 휴지통에서 복원할 수 있습니다.</p>`,()=>commit('사용하지 않는 교재 휴지통 이동',n=>M.trashBook(n,id)),'휴지통으로 이동')}
boot();

function individualEditor(id){const a=d.assignments.find(x=>x.id===id);scope(a.studentId);draftSteps=M.clone(a.customSteps??M.book(d,a.bookId).steps);open(student(a.studentId).name+' · 학생별 맞춤 과정',`<div class="note">이 학생의 교재 과정에만 적용됩니다. Unit별 맞춤 설정이 있는 Unit은 그 설정을 우선 사용합니다. 학습 기록이 있는 과정은 설명·페이지를 수정할 수 있어요.</div><div id="step-rows"></div>${btn('+ 단계 추가','add-individual-step','secondary','type="button"')}`,()=>{collectSteps();return commit('학생별 맞춤 학습 과정 저장',n=>M.saveIndividualSteps(n,id,draftSteps))});drawSteps()}
on('add-individual-step',()=>{staffOnly();collectSteps();draftSteps.push({id:M.uid(),name:'',desc:'',page:'',kind:''});dirty=true;drawSteps()});

on('students-active',()=>{studentListStatus='active';render()});
on('students-withdrawn',()=>{studentListStatus='withdrawn';render()});
function changeStudentStatus(id){adminOnly();const s=student(id);open(s.active?'퇴원 처리':'재등록',`<p><b>${E(s.name)}</b> 학생을 ${s.active?'퇴원생 목록으로 이동':'재원생 목록으로 복원'}할까요?</p><p class="note">학습·출결·수납 기록은 그대로 보존됩니다. 퇴원생은 오늘의 학습과 자동 청구 대상에서 제외됩니다. 기존 미납 내역은 유지됩니다.</p>`,()=>commit(s.active?'학생 퇴원 처리':'학생 재등록',n=>{const target=n.students.find(x=>x.id===id);target.active=!s.active;if(!target.active)target.withdrawnAt=M.today();else delete target.withdrawnAt}),s.active?'퇴원 처리':'재등록')}
function studentHistory(id){scope(id);const s=student(id);open(s.name+' · 보관 기록',`<h3>학습 기록</h3>${d.assignments.filter(a=>a.studentId===id).map(a=>`<p>${E(M.book(d,a.bookId)?.title)} · ${M.stats(d,a).percent}% 완료</p>`).join('')||'<p>학습 기록 없음</p>'}<h3>출결 기록</h3>${d.attendance.filter(a=>a.studentId===id).map(a=>`<p>${E(a.date)} · ${E(a.status||'등원')}</p>`).join('')||'<p>출결 기록 없음</p>'}${role==='admin'?`<h3>수납 기록</h3>${d.invoices.filter(a=>a.studentId===id).map(a=>`<p>${E(a.month)} · 청구 ${money(a.amount)} · 수납 ${money(M.paid(a))}${a.cancelled?' · 취소':''}</p>`).join('')||'<p>수납 기록 없음</p>'}`:''}`,()=>{},'확인')}

on('teachers-active',()=>{teacherListStatus='active';render()});
on('teachers-retired',()=>{teacherListStatus='retired';render()});
function changeTeacherStatus(id){adminOnly();const t=teacher(id),assigned=d.students.filter(s=>s.teacherId===id&&s.active),others=d.teachers.filter(x=>x.active&&x.id!==id);open(t.active?'교사 퇴사 처리':'교사 재직 복원',`<p><b>${E(t.name)}</b> 교사를 ${t.active?'퇴사 목록으로 이동':'재직 목록으로 복원'}할까요?</p>${t.active&&assigned.length?`<p>담당 재원생 ${assigned.length}명: ${assigned.map(s=>E(s.name)).join(' · ')}</p>${select('학생을 인계할 교사','replacement','<option value="">교사 선택</option>'+opts(others,x=>x.id,x=>x.name))}<p class="note">재원 학생의 담당 교사를 함께 변경합니다. 이전 담당 교사와 변경일은 이력에 보존됩니다.</p>`:'<p class="note">기존 지도 기록은 삭제하지 않습니다.</p>'}`,v=>{const replacement=v.get('replacement');if(t.active&&assigned.length&&!others.some(x=>x.id===replacement))throw Error('재원생을 인계할 재직 교사를 선택해 주세요. 필요하면 새 교사를 먼저 등록해 주세요.');return commit(t.active?'교사 퇴사·담당 학생 인계':'교사 재직 복원',n=>{const target=n.teachers.find(x=>x.id===id);target.active=!t.active;if(!target.active){target.retiredAt=M.today();for(const st of n.students.filter(x=>x.teacherId===id&&x.active)){st.teacherHistory??=[];st.teacherHistory.push({teacherId:id,changedAt:new Date().toISOString(),replacementId:replacement});st.teacherId=replacement}}else delete target.retiredAt})},t.active?'퇴사 처리':'재직 복원')}

function categoryTrashHTML(){return `<details class="card"><summary>삭제한 카테고리</summary>${(d.categories||[]).filter(c=>c.deletedAt&&c.deletionGroup===c.id).map(c=>`<div class="lab-item">${E(c.name)}${btn('복원',`category-recover:${c.id}`)}</div>`).join('')||'<p class="muted">삭제한 카테고리가 없습니다.</p>'}</details>`}
function removeCategoryDialog(id){adminOnly();const c=d.categories.find(x=>x.id===id);open('카테고리 삭제',`<p><b>${E(c.name)}</b> 카테고리를 삭제할까요?</p><p class="note">하위 카테고리도 함께 삭제됩니다. 해당 교재는 삭제하지 않고 ‘미분류’로 옮깁니다. 삭제한 카테고리에서 복원할 수 있습니다.</p>`,()=>commit('카테고리 삭제',n=>M.removeCategory(n,id)),'삭제')}
function unassignDialog(id){adminOnly();const a=d.assignments.find(x=>x.id===id);if(modal.open)modal.close();open('교재 배정 해제',`<p>${E(student(a.studentId)?.name)} · <b>${E(M.book(d,a.bookId)?.title)}</b></p><p class="note">학생의 현재 학습 목록에서 제외합니다. 교재 원본과 기존 진도 기록은 보존하며 ‘해제한 배정’에서 복원할 수 있습니다.</p>`,()=>commit('학생 교재 배정 해제',n=>M.setAssignmentArchived(n,id,true)),'배정 해제')}
function assignmentArchiveHTML(){return `<details style="margin-top:20px"><summary>해제한 배정 (기록 보존)</summary>${d.assignments.filter(a=>a.archived&&visibleStudents().some(s=>s.id===a.studentId)).map(a=>`<div class="lab-item"><span>${E(student(a.studentId)?.name)} · ${E(M.book(d,a.bookId)?.title)} · ${M.stats(d,a).percent}%</span>${role==='admin'?btn('배정 복원',`assignment-restore:${a.id}`):''}</div>`).join('')||'<p class="muted">해제한 배정이 없습니다.</p>'}</details>`}

function legacyCategoryLabels(){const all=(d.categories||[]).filter(c=>!c.deletedAt),managed=new Set(all.map(c=>{const p=all.find(x=>x.id===c.parentId);return p?p.name+' / '+c.name:c.name}));return [...new Set(d.books.filter(b=>!b.deletedAt).map(b=>b.category).filter(label=>label&&label!=='미분류'&&!managed.has(label)))]}
function legacyCategoriesHTML(){return `<section class="card"><h2>교재에 남아 있는 분류</h2><p class="muted">카테고리 관리에서 등록하지 않고 교재에 직접 입력했거나, 시연 교재에 포함된 분류입니다. 삭제하면 해당 교재는 미분류로 이동합니다.</p>${legacyCategoryLabels().map((label,index)=>`<div class="lab-item"><span>${E(label)}</span>${role==='admin'?btn('분류 삭제',`legacy-category-remove:${index}`,'danger'):''}</div>`).join('')||'<p class="muted">별도로 정리할 분류가 없습니다.</p>'}</section>`}
function removeLegacyCategory(index){adminOnly();const label=legacyCategoryLabels()[Number(index)];if(!label)throw Error('분류 목록을 다시 확인해 주세요.');open('교재 분류 삭제',`<p><b>${E(label)}</b> 분류를 삭제할까요?</p><p class="note">교재와 음원·학습 기록은 유지하고 분류만 미분류로 바꿉니다. 삭제한 카테고리에서 복원할 수 있습니다.</p>`,()=>commit('교재에 남은 분류 삭제',n=>{n.categories??=[];const id=M.uid();n.categories.push({id,name:label,parentId:null});M.removeCategory(n,id)}),'분류 삭제')}

function crossBookStepsHTML(id){const sources=d.books.filter(b=>b.id!==id&&!b.deletedAt&&b.steps.length);return `<section class="note"><h3>다른 교재의 기본 단계 가져오기</h3><p>단계 이름·학습 안내·페이지·연결 유형을 복사합니다. 음원 파일과 Unit별 맞춤 과정은 별도로 설정해 주세요.</p>${select('복사할 교재','copyBook','<option value="">교재 선택</option>'+opts(sources,b=>b.id,b=>b.title+' ('+b.steps.length+'단계)'))}${btn('기본 단계 미리보기','preview-book-steps','secondary','type="button"')}<div id="copy-book-preview"></div></section>`}
on('preview-book-steps',()=>{adminOnly();const source=M.book(d,$('[name="copyBook"]').value);if(!source||source.id===draftBook||source.deletedAt||!source.steps.length)throw Error('기본 단계가 있는 다른 교재를 선택해 주세요.');$('#copy-book-preview').innerHTML=`<p><b>${E(source.title)}</b> · ${source.steps.length}단계</p><ol>${source.steps.map(s=>`<li><b>${E(s.name)}</b> · ${E(s.page)}<p style="white-space:pre-wrap">${E(s.desc)}</p></li>`).join('')}</ol><p>가져오면 현재 편집 중인 단계를 바꿉니다. ‘과정 저장’을 눌러야 최종 반영됩니다.</p><button type="button" data-action="import-book-steps" data-source="${E(source.id)}">이 기본 단계 가져오기</button>`});
on('import-book-steps',el=>{adminOnly();const source=M.book(d,el.dataset.source);if(!source||source.deletedAt||source.id===draftBook)throw Error('복사할 교재를 다시 선택해 주세요.');const steps=source.steps.map(step=>({...M.clone(step),id:M.uid()}));const candidate=M.clone(d);M.saveSteps(candidate,draftBook,draftUnit,steps);collectSteps();draftSteps=steps;dirty=true;drawSteps();toast('기본 단계를 가져왔습니다. 내용을 확인한 뒤 과정 저장을 눌러 주세요.')});

function homeworkCell(s,r,field,label){const previous=M.previousHomework(d,s.id,dailyDate),taskKey=field+'Task',task=previous?.[taskKey]||'';return `<td class="daily-homework-col" style="min-width:220px;white-space:normal">${field==='personalHomework'?`<div style="font-size:12px;white-space:pre-wrap;margin-bottom:8px"><b>지난 숙제 ${task?E(previous.date):''}</b><br>${task?E(task):'등록된 숙제 내용 없음'}</div>`:''}<div class="hw-buttons" role="group" aria-label="${E(s.name)} ${label} 수행">${['O','X',''].map(value=>`<button class="${value==='O'?'hw-o':value==='X'?'hw-x':'hw-clear'} ${(r[field]??null)===(value||null)?'selected':''}" data-action="daily-homework" data-field="${field}" data-value="${value}" aria-label="${E(s.name)} ${label} ${value||'미입력'}" aria-pressed="${(r[field]??null)===(value||null)}">${value||'—'}</button>`).join('')}</div>${field==='personalHomework'?`<label style="font-size:12px;display:block;margin-top:8px">오늘 내준 ${label}<textarea class="daily-note" style="width:100%;min-height:65px" maxlength="1000" data-daily-field="${taskKey}" aria-label="${E(s.name)} 오늘 내준 ${label}" placeholder="예: Unit 3 단어 듣기 / 워크북 p.10">${E(r[taskKey]||'')}</textarea></label>`:''}${field==='wordHomework'&&r.homework?`<small>이전 통합 숙제 기록: ${E(r.homework)} (유지)</small>`:''}</td>`}
on('daily-reload',async()=>{staffOnly();await dailyFlush();if(dailyHasUnsaved())throw Error('저장하지 못한 기록을 먼저 확인해 주세요.');if(cloud)await boot();dailyInvalidateSaved();render();toast('최신 수업 기록을 불러왔습니다.')});

function groupedAssignmentsHTML(assignments){const groups=new Map();for(const a of assignments){if(!groups.has(a.studentId))groups.set(a.studentId,[]);groups.get(a.studentId).push(a)}return [...groups].map(([id,books])=>{const s=student(id);return `<details open class="assignment-student-group" data-assignment-group data-search="${E([s?.name,s?.grade,...books.map(a=>M.book(d,a.bookId)?.title)].join(' ').toLocaleLowerCase())}" style="border:1px solid var(--line);border-radius:14px;margin:12px 0;padding:16px"><summary style="cursor:pointer;font-weight:700">${E(s?.name)} <span class="muted">${E(s?.grade)} · ${books.length}권</span></summary>${books.map(a=>`<div class="lab-item"><div><b>📗 ${E(M.book(d,a.bookId)?.title)}</b><p class="muted">Unit ${M.nextUnit(d,a)} · ${M.stats(d,a).percent}% 완료 · ${a.days?.length?a.days.map(day=>'일월화수목금토'[day]).join('·'):'요일 미지정'}</p></div><div class="row">${btn('진도·요일 수정',`detail:${a.id}`)}${role==='admin'?btn('배정 해제',`unassign:${a.id}`,'danger'):''}</div></div>`).join('')}</details>`}).join('')||'<p class="empty">아직 배정된 교재가 없습니다.</p>'}
document.addEventListener('input',e=>{if(!e.target.hasAttribute('data-assignment-search'))return;const query=e.target.value.trim().toLocaleLowerCase();let count=0;document.querySelectorAll('[data-assignment-group]').forEach(group=>{group.hidden=!group.dataset.search.includes(query);if(!group.hidden){count++;if(query)group.open=true}});const empty=$('[data-assignment-empty]');if(empty)empty.hidden=count>0});

function studentScoreCard(s){if(!s.wordTestEnabled||studentFreeReview||M.isClassDay(d,s,M.today())===false)return '';const r=M.dailyRecord(d,s.id,M.today()),recorded=r?.wordScore!=null;return `<section class="card"><h2>📝 오늘 단어시험 점수</h2>${recorded?`<p>오늘 기록된 점수 <b>${E(r.wordScore)} / ${E(r.wordMax)}</b>개 정답 🌟</p><p class="muted">수정이 필요하면 선생님께 말씀해 주세요.</p>`:`<p>시험을 본 뒤 맞힌 개수와 전체 문항 수를 적어 주세요. 시험을 보지 않았다면 비워 두세요.</p><div class="row"><input id="student-word-score" aria-label="맞힌 개수" type="number" min="0" max="1000" step="1" inputmode="numeric" placeholder="맞힌 개수"><b>/</b><input id="student-word-total" aria-label="전체 문항 수" type="number" min="1" max="1000" step="1" inputmode="numeric" placeholder="전체 문항 수"><span>개</span>${btn('점수 제출','student-score-submit','')}</div>`}</section>`}
on('student-score-submit',async()=>{if(role!=='student')throw Error('학생 화면에서 제출해 주세요.');const input=$('#student-word-score');if(!input||input.value===''||!input.checkValidity())throw Error('시험 점수를 확인해 주세요. 0점도 입력할 수 있어요.');const totalInput=$('#student-word-total');if(!totalInput||totalInput.value===''||!totalInput.checkValidity())throw Error('전체 문항 수를 1~1000 사이로 입력해 주세요.');const score=Number(input.value),total=Number(totalInput.value);if(score>total)throw Error('맞힌 개수는 전체 문항 수보다 클 수 없어요.');if(cloud){const response=await fetch('/api/student-score',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId,score,total,expectedRevision:d.revision})});if(!response.ok){const result=await response.json();throw Error(result.error==='score_already_recorded'?'이미 기록된 점수가 있어요. 선생님께 확인해 주세요.':response.status===409?'최신 기록을 새로고침한 뒤 다시 확인해 주세요.':'점수를 저장하지 못했어요. 시험 대상과 점수를 확인해 주세요.')}await boot();toast('오늘 단어시험 점수를 저장했어요!')}else await commit('학생 단어시험 점수 제출',n=>recordStudentScore(n,studentId,score,M.today(),total))});
